const root = document.querySelector('#app');
const modal = document.querySelector('#modal');
const config = window.APP_CONFIG || {};
const blankGoals = { calories: 2000, proteinGrams: 150, carbsGrams: 250, fatGrams: 70, waterMl: 2500 };
const starterExercises = [['Barbell Shrug','Traps','Barbell'],['Dumbbell Shrug','Traps','Dumbbell'],['Bench Press (Barbell)','Chest','Barbell'],['Bench Press (Dumbbell)','Chest','Dumbbell'],['Back Squat','Quads','Barbell'],['Romanian Deadlift','Hamstrings','Barbell'],['Lat Pulldown','Back','Cable'],['Overhead Press','Shoulders','Barbell'],['Biceps Curl','Biceps','Dumbbell'],['Triceps Pushdown','Triceps','Cable']];
let exerciseChoices = [...starterExercises];
const state = { session: readSession(), page:'home', busy:false, message:'', profile:null, routines:[], sessions:[], foods:[], nutrition:null, date:null, today:null, clans:[], notices:[], challenges:[], activeWorkout:readWorkout(), username:'', exerciseDownloadBusy:false, coachRelationships:[], coachedAthlete:null, recovery:null, recoveryRows:[], workoutHistoryExpanded:false, homeWorkoutHistoryExpanded:false, timeZone:localStorage.getItem('gbNutritionTimeZone')||Intl.DateTimeFormat().resolvedOptions().timeZone };
state.today = state.date = localDate();
function readSession(){try{return JSON.parse(localStorage.getItem('gbWebSession')||'null')}catch{return null}}
function saveSession(s){state.session=s;if(s)localStorage.setItem('gbWebSession',JSON.stringify(s));else localStorage.removeItem('gbWebSession')}
function workoutStorageKey(userId=readSession()?.user?.id){return userId?`gbActiveWorkout:${userId}`:null}
function readWorkout(userId=readSession()?.user?.id){const key=workoutStorageKey(userId);if(!key)return null;try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}}
function persistWorkout(){const key=workoutStorageKey(state.session?.user?.id);if(!key)return;if(state.activeWorkout)localStorage.setItem(key,JSON.stringify(state.activeWorkout));else localStorage.removeItem(key)}
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:state.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone}).format(new Date())}
function uid(){return crypto.randomUUID()}
function loadExerciseCache(){try{const cached=JSON.parse(localStorage.getItem('gbExerciseCatalog')||'[]');if(Array.isArray(cached)&&cached.length)exerciseChoices=[...starterExercises,...cached]}catch{}}
function exerciseLabels(raw){const name=String(raw.name_en||'').trim();const source=`${raw.body_part||''} ${(raw.primary_muscles||[]).join(' ')} ${name}`.toLowerCase();const muscle=/trapezius|\btrap|shrug/.test(source)?'Traps':/chest|pector/.test(source)?'Chest':/shoulder|deltoid/.test(source)?'Shoulders':/biceps/.test(source)?'Biceps':/triceps/.test(source)?'Triceps':/forearm/.test(source)?'Forearms':/back|latissimus|rhomboid/.test(source)?'Back':/hamstring/.test(source)?'Hamstrings':/glute/.test(source)?'Glutes':/calf|soleus/.test(source)?'Calves':/abdominal|oblique|core/.test(source)?'Core':/quad|thigh|leg/.test(source)?'Legs':'Other';let equipment=String(raw.equipment||'').replaceAll('_',' ').trim();if(raw.is_bodyweight&&(!equipment||equipment==='other'))equipment='Bodyweight';equipment=equipment?equipment.replace(/\b\w/g,c=>c.toUpperCase()):'Other';return [name,muscle,equipment]}
async function downloadExerciseLibrary(){if(state.exerciseDownloadBusy)return;state.exerciseDownloadBusy=true;render();try{const response=await fetch('https://exercise-dataset.com/exercises.json',{mode:'cors',cache:'no-cache'});if(!response.ok)throw new Error(`Exercise catalog request failed (${response.status}).`);const json=await response.json(),rows=Array.isArray(json?.exercises)?json.exercises:[];const downloaded=[...new Map(rows.map(exerciseLabels).filter(x=>x[0]).map(x=>[x[0].toLowerCase(),x])).values()];if(downloaded.length<100)throw new Error('The exercise catalog was incomplete; try downloading again.');exerciseChoices=[...starterExercises,...downloaded.filter(x=>!starterExercises.some(s=>s[0].toLowerCase()===x[0].toLowerCase()))];localStorage.setItem('gbExerciseCatalog',JSON.stringify(exerciseChoices.slice(starterExercises.length)));flash(`${downloaded.length} exercises are ready. Search them while building a workout.`)}catch(error){flash(error.message||'Could not download the exercise catalog.','error')}finally{state.exerciseDownloadBusy=false;render()}}
function esc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function n(v,d=0){const x=Number(v);return Number.isFinite(x)?x:d}
function f(v,d=0){return new Intl.NumberFormat(undefined,{maximumFractionDigits:d}).format(n(v))}
function flash(m,k='info'){state.message=m;state.messageKind=k;render()}
function authUrl(p){return `${config.supabaseUrl.replace(/\/$/,'')}/auth/v1/${p}`}
function appCallbackUrl(){return new URL('./',location.href).toString()}
function apiUrl(p){return `${config.supabaseUrl.replace(/\/$/,'')}/rest/v1/${p}`}
function baseHeaders(){return {apikey:config.supabasePublishableKey,'Content-Type':'application/json'}}
function bearerHeaders(){if(!state.session?.access_token)throw new Error('Please sign in again.');return {...baseHeaders(),Authorization:`Bearer ${state.session.access_token}`}}
async function authRequest(path,body){const r=await fetch(authUrl(path),{method:'POST',headers:baseHeaders(),body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.msg||d.message||d.error_description||'Account request failed.');return d}
async function refreshTokenIfNeeded(){if(!state.session?.refresh_token||n(state.session.expires_at)>Date.now()/1000+60)return;const d=await authRequest('token?grant_type=refresh_token',{refresh_token:state.session.refresh_token});saveSession({...d,expires_at:Math.floor(Date.now()/1000)+n(d.expires_in,3600)})}
async function db(path,{method='GET',body,prefer='',query=''}={}){await refreshTokenIfNeeded();const h=bearerHeaders();if(prefer)h.Prefer=prefer;const r=await fetch(`${apiUrl(path)}${query?`?${query}`:''}`,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body)});const raw=await r.text();const d=raw?JSON.parse(raw):null;if(!r.ok)throw new Error(d?.message||d?.hint||d?.details||'Could not sync account data.');return d}
function rpc(name,args={}){return db(`rpc/${encodeURIComponent(name)}`,{method:'POST',body:args})}
function absorbAuthCallback(){const h=new URLSearchParams(location.hash.slice(1));if(h.has('access_token')){const token=h.get('access_token');let user=state.session?.user;try{const part=token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');const claims=JSON.parse(atob(part));user={id:claims.sub,email:claims.email}}catch{}saveSession({access_token:token,refresh_token:h.get('refresh_token'),expires_at:n(h.get('expires_at'),Date.now()/1000+3600),user});history.replaceState({},'',location.pathname+location.search)}}
function handleError(e){console.error(e);state.busy=false;flash(e?.message||'Something went wrong. Try again.','error')}
function normalizeNutrition(row){return row?{...row,foods:Array.isArray(row.foods)?row.foods:[],goals:{...blankGoals,...(row.goals||{})}}:{user_id:state.session.user.id,date:state.date,water_ml:0,foods:[],goals:{...blankGoals}}}
async function refreshData(){if(!state.session?.access_token)return render();state.activeWorkout=readWorkout(state.session.user.id);state.busy=true;render();try{await refreshTokenIfNeeded();const id=encodeURIComponent(state.session.user.id),requestedDate=state.date,priorToday=state.today;const [p,r,s,foods,nut,notices,clans,coachRelationships,recoveryRows]=await Promise.all([db('profiles',{query:`select=*&id=eq.${id}&limit=1`}),db('routines',{query:`select=*&user_id=eq.${id}&order=updated_at.desc`}),db('workout_sessions',{query:`select=*&user_id=eq.${id}&order=started_at.desc`}),db('user_foods',{query:`select=*&user_id=eq.${id}&order=name.asc`}),db('daily_nutrition',{query:`select=*&user_id=eq.${id}&date=eq.${requestedDate}&limit=1`}),db('clan_notifications',{query:`select=*&user_id=eq.${id}&order=created_at.desc&limit=25`}).catch(()=>[]),rpc('my_clans').catch(()=>[]),rpc('my_coach_relationships').catch(()=>[]),db('recovery_daily',{query:`select=*&user_id=eq.${id}&order=date.desc&limit=90`}).catch(()=>[])]);state.profile=p?.[0]||null;const savedZone=state.profile?.onboarding_data?.timeZone;if(savedZone){try{new Intl.DateTimeFormat('en',{timeZone:savedZone});state.timeZone=savedZone;localStorage.setItem('gbNutritionTimeZone',savedZone)}catch{}}state.today=localDate();if(requestedDate===priorToday||!requestedDate)state.date=state.today;const finalNutrition=state.date===requestedDate?nut:await db('daily_nutrition',{query:`select=*&user_id=eq.${id}&date=eq.${state.date}&limit=1`});if(state.profile&&state.username)state.profile={...state.profile,username:state.username};state.routines=(r||[]).map(x=>({...x,definition:x.definition||{}}));state.sessions=s||[];state.foods=(foods||[]).map(x=>({id:x.id,name:x.name,brand:x.brand||'',servingGrams:n(x.serving_grams,100),servingAmount:n(x.serving_amount,n(x.serving_grams,100)),servingUnit:x.serving_unit||'g',calories:Math.round(n(x.calories_per_serving,n(x.calories_per_100g)*n(x.serving_grams,100)/100)),proteinGrams:n(x.protein_per_serving,n(x.protein_per_100g)*n(x.serving_grams,100)/100),carbsGrams:n(x.carbs_per_serving,n(x.carbs_per_100g)*n(x.serving_grams,100)/100),fatGrams:n(x.fat_per_serving,n(x.fat_per_100g)*n(x.serving_grams,100)/100)}));state.nutrition=normalizeNutrition(finalNutrition?.[0]);state.notices=notices||[];state.clans=clans||[];state.coachRelationships=coachRelationships||[];state.recoveryRows=recoveryRows||[];state.recovery=state.recoveryRows[0]||null;state.busy=false;state.message='';render();if(state.page==='community')await loadChallenges()}catch(e){state.busy=false;throw e}}
const refreshDataWithoutWorkoutHeartRate = refreshData;
refreshData = async function refreshDataWithWorkoutHeartRate(){await refreshDataWithoutWorkoutHeartRate();if(!state.session?.user?.id||!state.sessions.length)return;const ids=[...new Set(state.sessions.slice(0,30).map(s=>String(s.id)).filter(id=>/^[0-9a-f-]{36}$/i.test(id)))];if(!ids.length)return;const rows=await db('heart_rate_samples',{query:`select=workout_session_id,bpm,measured_at,source,device_label&user_id=eq.${encodeURIComponent(state.session.user.id)}&workout_session_id=in.(${ids.join(',')})&order=measured_at.asc&limit=3000`}).catch(()=>[]);const grouped=new Map();for(const row of rows||[]){const bpm=n(row.bpm);if(bpm<30||bpm>240||!ids.includes(String(row.workout_session_id)))continue;const list=grouped.get(row.workout_session_id)||[];list.push({bpm,measuredAt:row.measured_at,source:row.source,deviceLabel:row.device_label});grouped.set(row.workout_session_id,list)}state.sessions=state.sessions.map(session=>({...session,heartRateSamples:grouped.get(session.id)||[]}));render()};
function heartRateSummary(samples){const values=(samples||[]).map(x=>n(x.bpm)).filter(x=>x>=30&&x<=240);return values.length?{average:Math.round(values.reduce((a,b)=>a+b,0)/values.length),peak:Math.max(...values),count:values.length}:null}
function bodyweightLoadFraction(exerciseName,equipment){if(!String(equipment||'').toLowerCase().includes('bodyweight'))return null;const name=String(exerciseName||'').toLowerCase().replaceAll('-',' ');if(name.includes('single leg glute bridge'))return .75;if(name.includes('glute bridge'))return .55;if(name.includes('incline push up'))return .45;if(name.includes('decline push up'))return .75;if(name.includes('push up')||name.includes('shoulder tap'))return .65;if(name.includes('pull up')||name.includes('chin up'))return 1;if(name.includes('dip'))return .85;if(name.includes('inverted row')||name.includes('towel row'))return .60;if(name.includes('squat')||name.includes('lunge')||name.includes('split squat')||name.includes('nordic curl'))return .90;if(name.includes('calf raise'))return .85;if(name.includes('leg raise')||name.includes('flutter kick'))return .50;if(name.includes('crunch')||name.includes('russian twist')||name.includes('dead bug')||name.includes('bird dog'))return .35;return .50}
function profileBodyWeightKg(profile=state.profile){const value=n(profile?.weight_value,NaN);if(!Number.isFinite(value)||value<=0)return 0;const kg=String(profile?.weight_unit||'kg').toLowerCase().startsWith('lb')?value/2.2046226218:value;return Number.isFinite(kg)&&kg>=30&&kg<=350?kg:0}
function effectiveBodyweightLoadKg(exercise,profile=state.profile){const fraction=bodyweightLoadFraction(exercise?.exercise?.name,exercise?.exercise?.equipment);return fraction==null?null:profileBodyWeightKg(profile)*fraction}
async function persistNutrition(next){next.updated_at=new Date().toISOString();state.nutrition=next;render();await db('daily_nutrition?on_conflict=user_id,date',{method:'POST',body:next,prefer:'resolution=merge-duplicates,return=minimal'})}
async function signIn(email,password,create=false){state.busy=true;render();try{const d=await authRequest(create?`signup?redirect_to=${encodeURIComponent(appCallbackUrl())}`:`token?grant_type=password`,{email,password});if(d.access_token){saveSession({...d,expires_at:Math.floor(Date.now()/1000)+n(d.expires_in,3600)});state.page='home';await refreshData()}else{state.busy=false;flash('Check your email to confirm your account, then sign in.')}}catch(e){state.busy=false;flash(e.message,'error')}}
async function signOut(){try{await fetch(authUrl('logout'),{method:'POST',headers:{...baseHeaders(),Authorization:`Bearer ${state.session?.access_token||''}`}})}catch{}saveSession(null);state.profile=null;state.routines=[];state.sessions=[];state.foods=[];state.nutrition=null;state.activeWorkout=null;state.page='home';render()}

loadExerciseCache();
if(!config.supabaseUrl||!config.supabasePublishableKey){root.innerHTML=`<main class="auth-shell"><section class="auth-art"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><h1>Build strength.<br><em>One rep at a time.</em></h1><p>Connect to the existing Anvil Quest Supabase project to use the same account and training data as Android.</p></section><section class="auth-card"><h2>Connection unavailable</h2><p class="muted">The browser could not load the public app configuration. Check your connection and try again.</p><p class="muted small">Only a publishable key belongs in browser code. Never use a service-role or secret key here.</p></section></main>`}else{absorbAuthCallback();render();if(state.session?.access_token)refreshData().catch(handleError)}

function render(){if(!state.session?.access_token){renderAuth();return}const pages={home:renderHome,workouts:renderWorkouts,nutrition:renderNutrition,community:renderCommunity,profile:renderProfile,progress:renderProgress,xp:renderXpJourney,avatar:renderAvatar,activity:renderActivity};const nav=[['home','⌂','Home'],['workouts','↗','Workout'],['nutrition','◒','Food'],['community','♧','Clan'],['progress','⌁','Progress'],['avatar','◉','Avatar'],['profile','◌','Profile']];root.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><nav class="nav">${nav.map(([id,icon,name])=>`<button data-nav="${id}" class="${state.page===id?'active':''}"><span>${icon}</span>${name}</button>`).join('')}</nav><div class="side-bottom">FORGE YOUR OWN PATH<br><span class="gold">${esc(state.profile?.training_path||'BUILDER')}</span><br><br><button class="button" data-action="refresh">SYNC ACCOUNT</button></div></aside><main class="main"><header class="topbar"><div class="eyebrow">${String(state.page).toUpperCase()} / THE ANVIL QUEST</div><div class="row"><span class="user-chip">${esc(state.profile?.username?`@${state.profile.username}`:state.session.user.email||'WARRIOR')}</span><button class="button" data-action="signout">SIGN OUT</button></div></header><div class="content">${state.message?`<div class="notice" role="status">${esc(state.message)}</div><div style="height:14px"></div>`:''}${state.busy?`<div class="notice">Syncing securely with your account…</div>`:''}${(pages[state.page]||renderHome)()}</div></main><nav class="mobile-nav">${nav.map(([id,icon,name])=>`<button data-nav="${id}" class="${state.page===id?'active':''}"><span>${icon}</span>${name}</button>`).join('')}</nav></div>`;if(state.page==='progress')requestAnimationFrame(renderMuscleMap);if(state.page==='avatar')requestAnimationFrame(renderAvatarMorphCanvases)}
function renderAuth(){root.innerHTML=`<main class="auth-shell"><section class="auth-art"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><div><div class="kicker">TRAIN • EAT • RECOVER</div><h1>Build strength.<br><em>One rep at a time.</em></h1><p>Your training log, saved workouts and nutrition travel with your account across Android and web.</p></div><div class="muted small">THE ANVIL QUEST · FORGE YOUR OWN PATH</div></section><section class="auth-card"><div class="mobile-only kicker">THE GODBUILDER</div><h2>${state.authMode==='signup'?'Create your account':'Welcome back'}</h2><p class="muted small">Use the same email and password as the Android app.</p><form id="auth-form"><div class="field"><label>Email</label><input class="input" type="email" name="email" autocomplete="email" required></div><div class="field"><label>Password</label><input class="input" type="password" name="password" minlength="6" autocomplete="${state.authMode==='signup'?'new-password':'current-password'}" required></div>${state.authMode==='signup'?`<label class="small muted"><input type="checkbox" name="marketing"> Send me optional product news</label>`:''}<div class="message">${esc(state.message)}</div><button class="button primary" ${state.busy?'disabled':''}>${state.busy?'PLEASE WAIT…':state.authMode==='signup'?'CREATE ACCOUNT':'SIGN IN'}</button></form><div class="row between" style="margin-top:12px"><button class="button" data-action="toggle-auth">${state.authMode==='signup'?'Already have an account?':'Create account'}</button><button class="button" data-action="reset-password">Forgot password?</button></div></section></main>`}
function head(k,t,d,a=''){return `<div class="page-head"><div><div class="kicker">${t==='Welcome'?'YOUR FORGE':k}</div><h1>${t}</h1><p>${d}</p></div>${a}</div>`}
function card(title,content){return `<section class="card"><h2>${title}</h2>${content}</section>`}
function localSessionDate(s){return new Date(s.started_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function localDay(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:state.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone}).format(date)}
function weekKey(date=new Date()){const parts=localDay(date).split('-').map(Number),d=new Date(Date.UTC(parts[0],parts[1]-1,parts[2]));d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
function targetPerWeek(){return Math.min(7,Math.max(1,n(state.profile?.onboarding_data?.sessionsPerWeek,3)))}
function completedSets(session){return (session.exercise_logs||[]).flatMap(e=>e.sets||[]).filter(s=>s.completed!==false&&String(s.set_type||s.setType||'WORKING').toUpperCase()==='WORKING')}
function xpLedger(sessions=state.sessions,target=targetPerWeek()){const ordered=[...sessions].filter(s=>completedSets(s).length).sort((a,b)=>new Date(a.started_at)-new Date(b.started_at)),best=new Map(),weekly=new Map(),days=new Map(),ledger=new Map();for(let i=0;i<ordered.length;i++){const s=ordered[i],sets=completedSets(s),date=new Date(s.started_at),day=localDay(date);let xp=Math.min(sets.length*10,100)+40+(i===0?100:0),prs=0;for(const ex of s.exercise_logs||[]){const name=String(ex.exercise?.name||ex.exercise_name||ex.name||'').trim().toLowerCase();if(!name)continue;const est=(ex.sets||[]).filter(x=>x.completed!==false&&String(x.set_type||x.setType||'WORKING').toUpperCase()==='WORKING').map(estimated1rm).filter(x=>x>0);const top=Math.max(0,...est);if(top>(best.get(name)||0)){prs++;best.set(name,top)}}xp+=Math.min(prs*25,75);const wk=weekKey(date),count=(weekly.get(wk)||0)+1;weekly.set(wk,count);if(count===target)xp+=75;const used=days.get(day)||0,awarded=Math.max(0,Math.min(xp,250-used));days.set(day,used+awarded);ledger.set(s.id,awarded)}return ledger}
function xpForSessions(sessions=state.sessions,target=targetPerWeek()){return [...xpLedger(sessions,target).values()].reduce((a,b)=>a+b,0)}
function sessionStats(){const currentWeek=weekKey(new Date()),w=state.sessions.filter(s=>weekKey(new Date(s.started_at))===currentWeek);return{week:w.length,volume:w.reduce((a,s)=>a+n(s.total_volume_kg),0),total:state.sessions.length,streak:weeklyStreak()}}
function weeklyStreak(){const goal=targetPerWeek(),counts=new Map();for(const s of state.sessions){const k=weekKey(new Date(s.started_at));counts.set(k,(counts.get(k)||0)+1)}const d=new Date(`${weekKey(new Date())}T00:00:00Z`);if((counts.get(d.toISOString().slice(0,10))||0)<goal)d.setUTCDate(d.getUTCDate()-7);let streak=0;while((counts.get(d.toISOString().slice(0,10))||0)>=goal){streak++;d.setUTCDate(d.getUTCDate()-7)}return streak}
function renderRecoveryCard(){const r=state.recovery;if(!r)return `<div><p class="muted small">Connect Health Connect in Android and allow recovery and activity access to share your latest summary here.</p><button class="button" data-nav="activity">VIEW ACTIVITY HISTORY</button></div>`;const details=[r.sleep_minutes!=null?`Sleep ${Math.floor(r.sleep_minutes/60)}h ${r.sleep_minutes%60}m`:null,r.hrv_millis!=null?`HRV ${f(r.hrv_millis)} ms`:null,r.resting_heart_rate!=null?`Resting HR ${f(r.resting_heart_rate)} bpm`:null].filter(Boolean).join(' · ');const activity=[r.steps!=null?`${f(r.steps)} steps`:null,r.daily_distance_meters!=null?`${f(r.daily_distance_meters/1000,1)} km distance today`:null,r.weekly_runs!=null?`${f(r.weekly_runs)} runs`:null,r.weekly_run_distance_meters!=null?`${f(r.weekly_run_distance_meters/1000,1)} km running`:null].filter(Boolean).join(' · ');return `<div><div class="row between"><strong class="gold">${r.recovery_score==null?'ACTIVITY':`${f(r.recovery_score)} / 100`}</strong><small class="muted">${esc(r.date)} · Android sync</small></div>${r.recovery_score==null?'':`<div class="progress" style="margin:8px 0"><i style="width:${Math.max(0,Math.min(100,n(r.recovery_score)))}%"></i></div>`}<p class="small muted">${esc(details||'No sleep or recovery signals synced yet.')}</p><p class="small muted">${esc(activity||'Steps and running metrics are unavailable.')}</p><small class="muted">Estimate only; not a medical assessment.</small><div style="margin-top:10px"><button class="button" data-nav="activity">VIEW ACTIVITY HISTORY</button></div></div>`}
function renderActivity(){const rows=[...(state.recoveryRows||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date)));if(!rows.length)return `${head('ACTIVITY','Recovery & activity','Wearable summaries synced through Health Connect on Android.')}<div class="card"><p class="muted">No activity history has synced yet. On Android, allow Recovery Data access in Settings; Fitbit and other devices need to sync their readings to Health Connect first.</p><button class="button" data-action="refresh">CHECK FOR SYNCED DATA</button></div>`;const latest=rows[0],recent=rows.slice(0,14),maxSteps=Math.max(1,...recent.map(x=>n(x.steps))),weeklyRun=latest.weekly_runs==null&&latest.weekly_run_distance_meters==null?'<div class="empty">No running summary synced.</div>':`<div class="grid stats"><div class="card stat"><div class="label">RUNS · LAST 7 DAYS</div><div class="value">${latest.weekly_runs==null?'—':f(latest.weekly_runs)}</div></div><div class="card stat"><div class="label">RUN DISTANCE · LAST 7 DAYS</div><div class="value">${latest.weekly_run_distance_meters==null?'—':`${f(latest.weekly_run_distance_meters/1000,1)} km`}</div></div></div>`;const bars=recent.slice().reverse().map(x=>`<div class="activity-bar-row"><span>${esc(new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(`${x.date}T12:00:00`)))}</span><div class="activity-bar-track"><i style="width:${Math.max(n(x.steps)?2:0,n(x.steps)/maxSteps*100)}%"></i></div><b>${x.steps==null?'—':f(x.steps)}</b></div>`).join('');const list=rows.slice(0,30).map(x=>`<div class="list-row"><div><strong>${esc(x.date)}</strong><small>${x.sleep_minutes==null?'Sleep —':`Sleep ${Math.floor(x.sleep_minutes/60)}h ${x.sleep_minutes%60}m`} · ${x.hrv_millis==null?'HRV —':`HRV ${f(x.hrv_millis)} ms`} · ${x.resting_heart_rate==null?'Resting HR —':`Resting HR ${f(x.resting_heart_rate)} bpm`}</small></div><span class="pill">${x.steps==null?'—':`${f(x.steps)} steps`}${x.daily_distance_meters==null?'':` · ${f(x.daily_distance_meters/1000,1)} km`}</span></div>`).join('');return `${head('ACTIVITY','Recovery & activity','Daily steps, distance, sleep and HRV, with your latest synced running summary.')}<div class="grid stats"><div class="card stat"><div class="label">LATEST RECOVERY</div><div class="value">${latest.recovery_score==null?'—':`${f(latest.recovery_score)} / 100`}</div><small class="muted">${latest.recovery_score==null?'No score available':`Updated ${esc(latest.date)}`}</small></div><div class="card stat"><div class="label">LATEST STEPS</div><div class="value">${latest.steps==null?'—':f(latest.steps)}</div><small class="muted">${esc(latest.date)}</small></div><div class="card stat"><div class="label">DAILY DISTANCE</div><div class="value">${latest.daily_distance_meters==null?'—':`${f(latest.daily_distance_meters/1000,1)} km`}</div><small class="muted">${esc(latest.date)}</small></div><div class="card stat"><div class="label">LATEST SLEEP</div><div class="value">${latest.sleep_minutes==null?'—':`${Math.floor(latest.sleep_minutes/60)}h ${latest.sleep_minutes%60}m`}</div><small class="muted">${esc(latest.date)}</small></div><div class="card stat"><div class="label">LATEST HRV</div><div class="value">${latest.hrv_millis==null?'—':`${f(latest.hrv_millis)} ms`}</div><small class="muted">Estimate from synced device data</small></div></div>${card(`Steps · last ${recent.length} synced days`,`<div class="activity-bars">${bars}</div>`)}<br>${card('Running · last 7 days',weeklyRun)}<br>${card('Daily recovery history',`<div class="list">${list}</div><p class="muted small">Showing up to 30 synced days. Data is read from Health Connect on Android; a wearable must first sync with Health Connect. Recovery scores are informational, not medical assessments.</p>`)}`}
function visibleHomeWorkoutHistory(sessions,expanded=false){return expanded?(sessions||[]):(sessions||[]).slice(0,3)}
function renderHome(){const s=sessionStats(),target=targetPerWeek(),xp=xpForSessions(state.sessions,target),prs=personalRecords();const recent=visibleHomeWorkoutHistory(state.sessions,state.homeWorkoutHistoryExpanded).map(x=>`<div class="list-row"><div><strong>${esc(x.title)}</strong><small>${localSessionDate(x)} · ${Math.round(n(x.duration_seconds)/60)} min</small></div><span class="pill">${f(x.total_volume_kg)} kg</span></div>`).join('')||`<div class="empty">Your first workout starts the journey.</div>`;const historyToggle=state.sessions.length>3?`<button class="button" data-action="toggle-home-workout-history">${state.homeWorkoutHistoryExpanded?'SHOW LESS':'SHOW ALL'} · ${state.sessions.length}</button>`:'';return `${head('YOUR FORGE',`Welcome${state.profile?.display_name?`, ${esc(state.profile.display_name)}`:''}`,'A clear view of the work you have put in.')}<div class="grid stats"><div class="card stat"><div class="label">WORKOUTS THIS WEEK · GOAL ${target}</div><div class="value">${s.week}<span class="muted" style="font-size:1rem"> / ${target}</span></div><div class="progress"><i style="width:${Math.min(100,s.week/target*100)}%"></i></div><small class="muted">Change goal in Profile · ${s.streak} week streak</small></div><div class="card stat"><div class="label">TOTAL WORKOUTS</div><div class="value">${s.total}</div><div class="muted small">Sessions saved</div></div><div class="card stat"><div class="label">TRAINING VOLUME</div><div class="value">${f(s.volume/1000,1)}<span class="muted" style="font-size:1rem"> t</span></div><div class="muted small">This week · kg</div></div><button class="card stat stat-button" data-nav="xp"><div class="label">XP JOURNEY</div><div class="value gold">${xp}</div><div class="muted small">Level ${Math.floor(xp/1000)+1} · View journey →</div></button></div><div class="grid two">${card(`Exercise PRs · ${prs.length}`,prs.length?`<div class="list">${prs.slice(0,6).map(x=>`<div class="list-row"><div><strong>${esc(x.name)}</strong><small>Estimated 1RM</small></div><span class="pill">${f(x.value,1)} kg</span></div>`).join('')}</div>${prs.length>6?`<button class="button" data-nav="progress">ALL EXERCISE RECORDS</button>`:''}`:`<div class="empty">Complete working sets to build your exercise strength history.</div>`)}${card('Recent sessions',recent+historyToggle+`<div style="margin-top:12px"><button class="button" data-nav="workouts">VIEW WORKOUTS</button></div>`)}${card('Your next session',`<p class="muted small">Pick up a saved routine or build today’s session.</p><div class="stack"><button class="button primary" data-action="new-routine">BUILD A WORKOUT</button><button class="button" data-nav="workouts">OPEN SAVED WORKOUTS</button></div>`)}${card('Recovery & activity',renderRecoveryCard())}${card('Issue with an exercise?',`<p class="muted small">MPT Dhruv Bawa · Physiotherapy consultation options</p><button class="button" data-action="physio">VIEW PHYSIO OPTIONS</button>`)}</div>`}
function estimated1rm(set){const weight=n(set.weight_kg??set.weightKg??set.weight),reps=n(set.reps);return weight>0&&reps>0&&reps<=12?weight*(1+reps/30):0}
function personalRecords(){const map=new Map();for(const session of state.sessions)for(const ex of session.exercise_logs||[]){const name=ex.exercise?.name||ex.exercise_name||ex.name||'Exercise',best=Math.max(0,...(ex.sets||[]).filter(s=>s.completed!==false&&String(s.set_type||s.setType||'WORKING').toUpperCase()==='WORKING').map(estimated1rm));if(best>(map.get(name)||0))map.set(name,best)}return[...map].map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value)}
function accountProgression(){
 const valid=state.sessions.filter(s=>Number.isFinite(new Date(s.started_at).getTime()));
 const activeDays=new Set(valid.map(s=>localDay(new Date(s.started_at)))).size;
 const activeWeeks=new Set(valid.map(s=>weekKey(new Date(s.started_at)))).size;
 const workouts=valid.length,volume=valid.reduce((a,s)=>a+n(s.total_volume_kg),0),reps=valid.reduce((a,s)=>a+n(s.total_reps),0),sets=valid.reduce((a,s)=>a+completedSets(s).length,0),xp=xpForSessions(valid);
 const score=(value,target)=>value<=0?0:Math.max(1,Math.min(99,Math.floor(Math.log1p(value)/Math.log1p(target)*99)));
 return{activeDays,activeWeeks,workouts,volume,reps,sets,xp,level:Math.floor(xp/1000)+1,attributes:[['STRENGTH',score(volume,5_000_000),`${f(volume)} / 5,000,000 kg`],['ENDURANCE',score(workouts,750),`${workouts} / 750 workouts`],['DISCIPLINE',score(activeWeeks,156),`${activeWeeks} / 156 active weeks`],['MASTERY',score(sets,5000),`${sets} / 5,000 working sets`]]};
}
function renderProgressAchievements(x){
 const data=[
  ['FIRST WORKOUT FORGED','Complete and log your first workout session.',x.workouts,1,'workouts'],['10 WORKOUTS COMPLETED','Log 10 workouts.',x.workouts,10,'workouts'],['THIRTY DAYS FORGED','Train on 30 separate calendar days.',x.activeDays,30,'training days'],['250 WORKING SETS','Complete 250 working sets.',x.sets,250,'working sets'],['5,000 KG FORGED','Lift 5,000 kg of total logged workout volume.',x.volume,5000,'kg'],['50,000 KG HEAVY VOLUME','Cross 50,000 kg of total logged volume.',x.volume,50000,'kg'],['VETERAN OF THE ANVIL','Log 50 completed workouts.',x.workouts,50,'workouts'],['CENTURION','Complete 100 workouts.',x.workouts,100,'workouts'],['IRON LEGION','Complete 250 workouts.',x.workouts,250,'workouts'],['TEN THOUSAND REPS','Log 10,000 completed reps.',x.reps,10000,'reps'],['HALF MILLION KG','Lift 500,000 kg of logged volume.',x.volume,500000,'kg'],['YEAR OF THE FORGE','Train in 52 distinct calendar weeks.',x.activeWeeks,52,'active weeks'],['LEVEL 25','Earn enough workout XP to reach level 25.',x.xp,24000,'XP'],['LEVEL 50','Earn enough workout XP to reach level 50.',x.xp,49000,'XP'],['2,500 WORKING SETS','Complete 2,500 working sets.',x.sets,2500,'working sets'],['A THOUSAND SESSIONS','Complete 1,000 logged workouts.',x.workouts,1000,'workouts'],['MILLION KILOGRAMS','Lift 1,000,000 kg of total logged volume.',x.volume,1000000,'kg'],['TEN THOUSAND SETS','Complete 10,000 working sets.',x.sets,10000,'working sets'],['THREE YEARS ON THE ANVIL','Train in 156 distinct calendar weeks.',x.activeWeeks,156,'active weeks'],['LEVEL 100','Earn enough workout XP to reach level 100.',x.xp,99000,'XP']
 ];
 const earned=data.filter(b=>b[2]>=b[3]).length;
 const cards=data.map(([title,description,value,target,unit])=>{const unlocked=value>=target,progress=Math.min(value,target);return `<article class="badge-card ${unlocked?'earned':''}"><span class="badge-mark" aria-hidden="true">${unlocked?'◆':'◇'}</span><div class="badge-copy"><strong>${esc(title)}</strong><small>${esc(description)}</small><small>${f(progress)} / ${f(target)} ${esc(unit)}</small></div><span class="pill">${unlocked?'EARNED':'LOCKED'}</span></article>`}).join('');
 return card(`Achievements · ${earned} / ${data.length}`,`<div class="badge-grid">${cards}</div>`);
}
function renderStrengthHistory(prs){
 return card('Exercise strength',prs.length?`<p class="muted small">Estimated 1RM from completed working sets of 1–12 reps; this is a calculation, not a max-lift test.</p><div class="list">${prs.map(p=>{const history=state.sessions.map(s=>({date:new Date(s.started_at),best:Math.max(0,...(s.exercise_logs||[]).filter(e=>(e.exercise?.name||e.exercise_name||e.name||'').toLowerCase()===p.name.toLowerCase()).flatMap(e=>e.sets||[]).filter(x=>x.completed!==false).map(estimated1rm))})).filter(x=>x.best>0).sort((a,b)=>a.date-b.date);const delta=history.length>1?history.at(-1).best-history.at(-2).best:null;return `<div class="list-row"><div><strong>${esc(p.name)}</strong><small>Estimated 1RM best${delta===null?'':` · ${delta>=0?'+':''}${f(delta,1)} kg since last session`}</small></div><span class="pill">${f(p.value,1)} kg</span></div>`}).join('')}</div>`:`<div class="empty">Complete a workout with logged sets to start your strength and personal-record history.</div>`);
}
function muscleKey(ex){
 const raw=String(ex?.exercise?.muscleGroup||ex?.muscle_group||ex?.muscle||'').trim().toLowerCase();
 const name=String(ex?.exercise?.name||ex?.exercise_name||ex?.name||'').toLowerCase();
 const explicit={chest:'Chest',pectorals:'Chest',pectoral:'Chest',back:'Back',shoulders:'Shoulders',shoulder:'Shoulders',deltoids:'Shoulders',deltoid:'Shoulders',traps:'Traps',trap:'Traps',trapezius:'Traps',biceps:'Biceps',bicep:'Biceps',triceps:'Triceps',tricep:'Triceps',forearms:'Forearms',forearm:'Forearms',quads:'Quads',quadriceps:'Quads',hamstrings:'Hamstrings',hamstring:'Hamstrings',glutes:'Glutes',glute:'Glutes',calves:'Calves',calf:'Calves',abs:'Core',abdominals:'Core',core:'Core',obliques:'Core',oblique:'Core'}[raw];
 if(explicit)return explicit;
 if(/shrug|trapezius|\btraps?\b/.test(name))return'Traps';
 if(/deadlift|\brow\b|pulldown|pull[- ]?up|chin[- ]?up|pullover/.test(name)&&!/upright row/.test(name))return'Back';
 if(/chest|pector/.test(name))return'Chest';
 if(/shoulder|deltoid|lateral raise|front raise|face pull|rear delt|reverse fly|upright row/.test(name))return'Shoulders';
 if(/biceps?|curl/.test(name)&&!/leg curl|hamstring curl/.test(name))return'Biceps';
 if(/triceps?/.test(name))return'Triceps';
 if(/forearm|wrist curl/.test(name))return'Forearms';
 if(/hamstring|leg curl|romanian deadlift/.test(name))return'Hamstrings';
 if(/glute|hip thrust/.test(name))return'Glutes';
 if(/calf|calves/.test(name))return'Calves';
 if(/quad|thigh|leg extension|squat|lunge/.test(name))return'Quads';
 if(/abdominal|\babs?\b|core|oblique|plank|crunch|twist/.test(name))return'Core';
 return null
}
function muscleTotals(days=30){const since=days==='all'?0:Date.now()-days*86400000,totals={};for(const session of state.sessions){if(new Date(session.started_at).getTime()<since)continue;for(const ex of session.exercise_logs||[]){const group=muscleKey(ex);if(!group)continue;const count=(ex.sets||[]).filter(s=>s.completed!==false&&String(s.set_type||s.setType||'WORKING').toUpperCase()==='WORKING').length;if(count)totals[group]=(totals[group]||0)+count}}return totals}
function muscleMapTargets(ex){
 const primary=muscleKey(ex),name=String(ex?.exercise?.name||ex?.exercise_name||ex?.name||'').toLowerCase(),logical={};
 const addLogical=(group,weight=1)=>{logical[group]=Math.max(logical[group]||0,weight)};
 const targets={};const add=(region,weight=1)=>{targets[region]=Math.max(targets[region]||0,weight)};
 if(primary)addLogical(primary);
 if(primary==='Chest'&&/bench|press|push[- ]?up/.test(name)){addLogical('Triceps',.45);addLogical('Shoulders',.45)}
 if(primary==='Shoulders'&&/shoulder press|overhead press|arnold press|pike push/.test(name))addLogical('Triceps',.45);
 if(primary==='Back'&&/\brow\b|pulldown|pull[- ]?up|chin[- ]?up/.test(name))addLogical('Biceps',.45);
 for(const [group,weight]of Object.entries(logical)){
  if(group==='Chest')add('CHEST',weight);
  else if(group==='Shoulders'){
   if(/bench|chest press|push[- ]?up|chest fly|crossover/.test(name))add('SHOULDERS_FRONT',weight);
   else if(/lateral raise|upright row/.test(name))add('SHOULDERS_SIDE',weight);
   else if(/rear delt|reverse fly|reverse pec|face pull/.test(name))add('SHOULDERS_REAR',weight);
   else if(/front raise|overhead press|shoulder press|arnold press|pike push/.test(name)){add('SHOULDERS_FRONT',weight);add('SHOULDERS_SIDE',weight*.65)}
   else{add('SHOULDERS_FRONT',weight);add('SHOULDERS_SIDE',weight);add('SHOULDERS_REAR',weight)}
  }
  else if(group==='Back'){
   if(/deadlift|back extension|good morning/.test(name)){add('BACK_LOWER',weight);add('HAMSTRINGS',weight*.45);add('GLUTES',weight*.45)}
   else if(/\brow\b/.test(name)){add('RHOMBOIDS',weight);add('LATS',weight*.65);add('SHOULDERS_REAR',weight*.35)}
   else if(/pulldown|pull[- ]?up|chin[- ]?up|pullover/.test(name))add('LATS',weight);
   else{add('LATS',weight);add('RHOMBOIDS',weight*.7)}
  }
  else if(group==='Traps')add('TRAPEZIUS',weight);
  else if(group==='Biceps')add('BICEPS',weight);
  else if(group==='Triceps')add('TRICEPS',weight);
  else if(group==='Forearms')add('FOREARMS',weight);
  else if(group==='Quads')add('QUADS',weight);
  else if(group==='Hamstrings')add('HAMSTRINGS',weight);
  else if(group==='Glutes')add('GLUTES',weight);
  else if(group==='Calves')add('CALVES',weight);
  else if(group==='Core')add(/twist|oblique|side bend/.test(name)?'OBLIQUES':'CORE',weight);
 }
 return Object.entries(targets)
}
function muscleMapTotals(days=30){const since=days==='all'?0:Date.now()-days*86400000,totals={};for(const session of state.sessions){if(new Date(session.started_at).getTime()<since)continue;for(const ex of session.exercise_logs||[]){const count=(ex.sets||[]).filter(s=>s.completed!==false&&String(s.set_type||s.setType||'WORKING').toUpperCase()==='WORKING').length;if(!count)continue;for(const [region,weight]of muscleMapTargets(ex))totals[region]=(totals[region]||0)+count*weight}}return totals}
function renderMuscleMap(){const host=document.querySelector('#progress-muscle-map');if(!host)return;const days=state.musclePeriod||30,regionTotals=muscleMapTotals(days),max=Math.max(1,...Object.values(regionTotals)),gender=state.profile?.gender==='Female'?'female':'male',accent=state.profile?.training_path==='TITAN'?'#b477e8':state.profile?.training_path==='SUPERHERO'?'#54b7f4':'#d6a84f';host.style.setProperty('--map-accent',accent);host.querySelector('.muscle-figures').innerHTML='<div class="map-loading">Loading anatomy map…</div>';Promise.all(['front','back'].map(async side=>{const response=await fetch(`./musclemap/${gender}-${side}.svg`);if(!response.ok)throw new Error('Could not load muscle map');return response.text()})).then(([front,back])=>{if(!host.isConnected)return;host.querySelector('.muscle-figures').innerHTML=`<div class="muscle-figure"><div class="muscle-svg">${front}</div><span>FRONT</span></div><div class="muscle-figure"><div class="muscle-svg">${back}</div><span>BACK</span></div>`;host.querySelectorAll('.muscle').forEach(path=>{const group=path.dataset.group,sets=regionTotals[group]||0,intensity=sets?Math.min(1,sets/max):0;path.style.fill=sets?accent:'rgba(147,151,162,.12)';path.style.stroke=sets?accent:'rgba(235,238,244,.30)';path.style.strokeWidth=sets?'2.5':'1.3';path.style.opacity=sets?String(.45+intensity*.5):'.8';path.style.filter=sets&&intensity>.65?`drop-shadow(0 0 2px ${accent})`:''});}).catch(()=>{if(host.isConnected)host.querySelector('.muscle-figures').innerHTML='<div class="map-loading">Muscle map is unavailable. Your workout records are still saved.</div>'})}
function renderProgress(){
 const stats=sessionStats(),target=targetPerWeek(),prs=personalRecords(),x=accountProgression();
 const attributes=x.attributes.map(([name,value,detail])=>`<div class="attribute-row"><div class="row between"><strong>${esc(name)}</strong><span class="pill">LVL ${value}</span></div><div class="progress"><i style="width:${value}%"></i></div><small class="muted">${esc(detail)}</small></div>`).join('');
 const totals=muscleTotals(state.musclePeriod||30),worked=Object.keys(totals).length;
 return `${head('YOUR PROGRESS','Progress','Training consistency, strength estimates, achievements, and work completed.')}<div class="grid stats"><div class="card stat"><div class="label">THIS WEEK</div><div class="value">${stats.week} / ${target}</div><div class="muted small">workouts</div></div><div class="card stat"><div class="label">WEEKLY STREAK</div><div class="value">${stats.streak}</div><div class="muted small">${stats.streak===1?'week':'weeks'}</div></div><div class="card stat"><div class="label">VOLUME THIS WEEK</div><div class="value">${f(stats.volume)} kg</div><div class="muted small">weight × reps</div></div><div class="card stat"><div class="label">COMPLETED WORKOUTS</div><div class="value">${stats.total}</div><div class="muted small">in history</div></div></div>${card(`Muscle map · ${worked} groups trained`,`<div class="row between muscle-map-controls"><p class="muted small">Each muscle fills from completed working sets in this period.</p><select class="input muscle-period" data-action="muscle-period" aria-label="Muscle map time period"><option value="7" ${state.musclePeriod===7?'selected':''}>7 days</option><option value="30" ${(state.musclePeriod||30)===30?'selected':''}>30 days</option><option value="90" ${state.musclePeriod===90?'selected':''}>90 days</option><option value="all" ${state.musclePeriod==='all'?'selected':''}>All time</option></select></div><div id="progress-muscle-map" class="progress-muscle-map" aria-label="Front and back muscle activity map"><div class="muscle-figures"><div class="map-loading">Loading anatomy map…</div></div><div class="muscle-legend"><span></span> TRAINED IN SELECTED PERIOD</div></div><div class="muscle-counts">${['Chest','Back','Shoulders','Traps','Biceps','Triceps','Quads','Hamstrings','Glutes','Calves','Core','Forearms'].map(g=>`<span>${g}<b>${totals[g]||0} sets</b></span>`).join('')}</div><small class="muted">Muscle-map anatomy: Jsplice / MuscleMap, MIT License. <a href="https://github.com/Jsplice/MuscleMap" target="_blank" rel="noopener noreferrer">Source and license</a>.</small>`)}<br><div class="grid two">${card('Warrior attributes',`<div class="attribute-grid">${attributes}</div><p class="muted small">Ratings grow slowly toward long-term milestones. Each attribute caps at level 99.</p>`)}${renderStrengthHistory(prs)}</div><br>${renderProgressAchievements(x)}`;
}
function renderXpJourney(){const target=targetPerWeek(),ledger=xpLedger(state.sessions,target),xp=[...ledger.values()].reduce((a,b)=>a+b,0),level=Math.floor(xp/1000)+1,into=xp%1000;return `${head('YOUR JOURNEY','XP Journey','Progress is calculated from completed workout history and shared with Android.')}<section class="card"><div class="kicker">LEVEL ${level}</div><div class="value gold">${xp} XP</div><p>${into} / 1,000 XP to level ${level+1}</p><div class="progress"><i style="width:${into/10}%"></i></div></section><br>${card('Earned from training',state.sessions.length?`<div class="list">${[...state.sessions].sort((a,b)=>new Date(b.started_at)-new Date(a.started_at)).map(s=>`<div class="list-row"><div><strong>${esc(s.title||'Workout')}</strong><small>${localSessionDate(s)}</small></div><span class="pill">+${n(ledger.get(s.id))} XP</span></div>`).join('')}</div>`:`<div class="empty">Complete a workout to begin your XP journey.</div>`)}`}
function exerciseGlyph(value){const x=value?.exercise||value||{},eq=String(x.equipment||'').toLowerCase();let art;if(eq.includes('barbell'))art='<path d="M4 16h24M7 9v14M11 11v10M21 11v10M25 9v14"/>';else if(eq.includes('dumbbell'))art='<path d="M6 16h20M8 11v10M12 13v6M20 13v6M24 11v10"/>';else if(eq.includes('cable'))art='<path d="M8 5v22M24 5v22M8 7h16M24 10 17 21M14 21h6"/><circle cx="24" cy="10" r="1.8"/>';else if(eq.includes('machine'))art='<path d="M8 5v22M24 5v22M8 7h16M12 12h8v6h-8zM10 23h12"/>';else if(eq.includes('bodyweight'))art='<path d="M5 23h22M7 19c4-10 14-10 18 0M22 16l3 3-1 4"/>';else if(eq.includes('band'))art='<path d="M5 12h4l3 8 4-16 4 16 3-8h5"/>';else art='<path d="M12 12V9a4 4 0 0 1 8 0v3M9 13c-3 4-2 12 7 12s10-8 7-12z"/>';return `<span class="exercise-icon" aria-hidden="true"><svg viewBox="0 0 32 32" focusable="false">${art}</svg></span>`}
function visibleWorkoutHistory(sessions,expanded=false){return (sessions||[]).slice(0,expanded?30:3)}
function renderWorkouts(){const routines=state.routines.map(r=>{const d=r.definition||{},ex=d.exercises||[];return `<div class="list-row"><div><strong>${esc(r.title||d.title||'Workout')}</strong><small>${ex.length} exercises · ${ex.reduce((a,e)=>a+(e.sets||[]).filter(s=>s.setType!=='WARMUP').length,0)} sets</small></div><div class="row"><button class="button" data-action="view-routine" data-id="${esc(r.id)}">VIEW</button><button class="button primary" data-action="start-workout" data-id="${esc(r.id)}">START</button></div></div>`}).join('')||`<div class="empty">No saved routines yet. Build a workout to start.</div>`;const sessions=visibleWorkoutHistory(state.sessions,state.workoutHistoryExpanded).map(s=>{const hr=heartRateSummary(s.heartRateSamples);return `<div class="list-row"><div><strong>${esc(s.title)}</strong><small>${localSessionDate(s)} · ${Math.round(n(s.duration_seconds)/60)} min · ${n(s.total_reps)} reps${hr?` · HR avg ${hr.average} · peak ${hr.peak} BPM`:''}</small></div><div class="row"><span class="pill">${f(s.total_volume_kg)} kg</span><button class="button danger" data-action="delete-session" data-id="${esc(s.id)}">DELETE</button></div></div>`}).join('')||`<div class="empty">Completed workouts will appear here.</div>`;const historyToggle=state.sessions.length>3?`<button class="button" data-action="toggle-workout-history">${state.workoutHistoryExpanded?'SHOW FEWER':'SHOW ALL'} · ${state.sessions.length}</button>`:'';return `${head('TRAINING HALL','Workouts','Create routines and keep your training history.',`<button class="button" data-action="download-exercises" ${state.exerciseDownloadBusy?'disabled':''}>${state.exerciseDownloadBusy?'DOWNLOADING…':exerciseChoices.length>starterExercises.length?`${exerciseChoices.length} EXERCISES READY · UPDATE`:'DOWNLOAD EXERCISE LIBRARY'}</button><button class="button primary" data-action="new-routine">+ BUILD ROUTINE</button>`)}${state.activeWorkout?`<div class="notice row between"><span>Workout in progress · ${esc(state.activeWorkout.title)}</span><button class="button" data-action="resume-workout">RESUME</button></div><br>`:''}<div class="grid two">${card('Saved workouts',`<div class="list">${routines}</div>`)}${card('Completed sessions',`<div class="list">${sessions}</div>${historyToggle}`)}</div>`}
function renderNutrition(){
  const x=state.nutrition||normalizeNutrition(null),g=x.goals||blankGoals,foods=x.foods||[];
  const total=foods.reduce((a,z)=>({cal:a.cal+n(z.calories),p:a.p+n(z.proteinGrams),c:a.c+n(z.carbsGrams),fat:a.fat+n(z.fatGrams)}),{cal:0,p:0,c:0,fat:0});
  const logs=foods.map(z=>`<div class="list-row"><div><strong>${esc(z.name)}</strong><small>${f(z.servingAmount??z.grams,2)} ${esc(z.servingUnit||'g')} · ${f(z.calories)} kcal · P${f(z.proteinGrams)} C${f(z.carbsGrams)} F${f(z.fatGrams)} g</small></div><button class="button danger" data-action="remove-food" data-id="${esc(z.id)}" ${state.date!==state.today?'disabled':''}>REMOVE</button></div>`).join('')||`<div class="empty">Nothing logged for this day.</div>`;
  const saved=state.foods.map(z=>`<div class="list-row"><div><strong>${esc(z.name)}</strong><small>${f(z.servingAmount,2)} ${esc(z.servingUnit)} per serving · ${f(z.calories)} kcal · P${f(z.proteinGrams)} C${f(z.carbsGrams)} F${f(z.fatGrams)}</small></div><div class="row"><button class="button danger" data-action="delete-saved-food" data-id="${esc(z.id)}">DELETE</button><button class="button" data-action="log-saved-food" data-id="${esc(z.id)}">LOG</button></div></div>`).join('')||`<div class="empty">Save foods you use often, then log any quantity.</div>`;
  const old=state.date!==state.today;
  return `${head('FUEL LOG','Nutrition',old?`History · ${state.date} · view only`:`Your day resets at midnight (${esc(state.timeZone)}). Save foods once and log quantities later.`,`<button class="button primary" data-action="new-food">+ CREATE FOOD</button>`)}<section class="card"><div class="row between"><button class="button" data-action="date-prev">← PREVIOUS DAY</button><input class="input" type="date" id="nutrition-date" value="${esc(state.date)}" max="${esc(state.today)}"><button class="button" data-action="date-next" ${old?'':'disabled'}>NEXT →</button></div><p class="kicker" style="margin:14px 0 0">${old?'HISTORY · VIEW ONLY':'TODAY'}</p></section><div class="grid stats"><div class="card stat"><div class="label">CALORIES</div><div class="value">${f(total.cal)}<span class="muted" style="font-size:.8rem"> / ${f(g.calories)}</span></div><div class="progress"><i style="width:${Math.min(100,total.cal/Math.max(1,g.calories)*100)}%"></i></div></div><div class="card stat"><div class="label">PROTEIN</div><div class="value">${f(total.p)}<span class="muted" style="font-size:.8rem"> / ${f(g.proteinGrams)}g</span></div></div><div class="card stat"><div class="label">CARBS</div><div class="value">${f(total.c)}<span class="muted" style="font-size:.8rem"> / ${f(g.carbsGrams)}g</span></div></div><div class="card stat"><div class="label">FAT</div><div class="value">${f(total.fat)}<span class="muted" style="font-size:.8rem"> / ${f(g.fatGrams)}g</span></div></div></div><div class="grid two">${card(old?'Food log':'Today’s food',logs+(!old?`<button class="button primary" data-action="new-food">LOG FOOD</button>`:''))}${card('Hydration',`<div class="value">${f(x.water_ml)} ml</div><div class="muted small">Goal ${f(g.waterMl)} ml</div><div class="row" style="margin-top:14px">${[250,500,750].map(v=>`<button class="button" data-action="add-water" data-value="${v}" ${old?'disabled':''}>+${v} ml</button>`).join('')}</div><div style="margin-top:12px"><button class="button" data-action="water-custom" ${old?'disabled':''}>OTHER AMOUNT</button></div>`)}${card('My foods',`<p class="muted small">Each saved food stores macros per serving. Choose a food, enter how many servings, and review the multiplied totals.</p><div class="list">${saved}</div>`)}</div>`
}
function renderAvatarLegacy(){const p=state.profile||{},xp=xpForSessions(state.sessions,targetPerWeek()),level=Math.floor(xp/1000)+1,stage=level>=10?3:level>=5?2:1,path=['SUPERHERO','TITAN'].includes(String(p.training_path||'').toUpperCase())?String(p.training_path).toLowerCase():'god',gender=String(p.gender||'Male').toLowerCase().includes('fem')?'female':'male',base=`${config.supabaseUrl.replace(/\/$/,'')}/storage/v1/object/public/godbuilder-site/avatarpack`;const choices=[['GOD','male','God · Male'],['GOD','female','God · Female'],['SUPERHERO','male','Superhero · Male'],['SUPERHERO','female','Superhero · Female'],['TITAN','male','Titan · Male'],['TITAN','female','Titan · Female']];const image=(kind,sex,levelStage,extra='')=>`<div class="avatar-art ${extra}"><img src="${base}/avatar_${kind.toLowerCase()}_${sex}_stage_${levelStage}.png" alt="${kind} ${sex} avatar, stage ${levelStage}" loading="lazy" onerror="this.parentElement.classList.add('unavailable')"><span class="avatar-fallback" aria-hidden="true">${kind}<small>${sex.toUpperCase()}</small></span></div>`;const modelCards=choices.map(([kind,sex,label])=>`<article class="avatar-choice ${kind.toLowerCase()===path&&sex===gender?'selected':''}">${image(kind.toLowerCase(),sex,1)}<div><strong>${label}</strong><small>${kind.toLowerCase()===path&&sex===gender?'CURRENT MODEL':'Set in Profile'}</small></div></article>`).join('');return `${head('AVATAR','Your avatar','Your training path, level and recovery journey in one place.')}<div class="grid two"><section class="card avatar-current"><div class="kicker">${esc(String(p.training_path||'GOD').toUpperCase())} PATH · ${gender.toUpperCase()}</div>${image(path,gender,stage,'avatar-main-art')}<h2>LEVEL ${level} · STAGE ${stage}</h2><p class="muted small">${f(xp)} total XP · ${stage===1?`${Math.max(0,4000-xp)} XP to Stage 2`:stage===2?`${Math.max(0,9000-xp)} XP to Stage 3`:'Stage 3 reached'}</p><div class="progress"><i style="width:${stage===1?Math.min(100,xp/40):stage===2?Math.min(100,(xp-4000)/50):100}%"></i></div><p class="muted small">The avatar follows your gender and training path from Profile. New stage artwork downloads only when needed and stays cached on this device.</p><button class="button" data-nav="profile">EDIT PATH & PRESENTATION</button></section>${card('Six avatar models',`<p class="muted small">Choose a path and presentation in Profile. The stage shown here follows your workout XP.</p><div class="avatar-grid">${modelCards}</div>`)}</div>`}
function renderProfile(){const p=state.profile||{},zones=(Intl.supportedValuesOf?.('timeZone')||[]).map(z=>`<option value="${esc(z)}"></option>`).join('');return `${head('BUILDER PROFILE','Your profile','The same account and training history as Android.')}<div class="grid two">${card('Training identity',`<div class="stack"><div class="field"><label>Display name</label><input class="input" id="profile-name" value="${esc(p.display_name||p.name||'')}" maxlength="60"></div><div class="form-grid"><div class="field"><label>Gender</label><select id="profile-gender"><option ${p.gender==='Male'?'selected':''}>Male</option><option ${p.gender==='Female'?'selected':''}>Female</option></select></div><div class="field"><label>Path</label><select id="profile-path">${['GOD','SUPERHERO','TITAN'].map(x=>`<option ${p.training_path===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="form-grid"><div class="field"><label>Body weight (for bodyweight exercise estimates)</label><input class="input" id="profile-weight" type="number" min="30" max="770" step="0.1" value="${p.weight_value==null?'':esc(p.weight_value)}" placeholder="Optional"></div><div class="field"><label>Weight unit</label><select id="profile-weight-unit"><option value="kg" ${(p.weight_unit||'kg')==='kg'?'selected':''}>kg</option><option value="lb" ${p.weight_unit==='lb'?'selected':''}>lb</option></select></div></div><div class="field"><label>Weekly workout goal</label><select id="profile-goal">${[1,2,3,4,5,6,7].map(x=>`<option value="${x}" ${n(p.onboarding_data?.sessionsPerWeek,3)===x?'selected':''}>${x} workouts / week</option>`).join('')}</select></div><div class="field"><label>Nutrition day time zone</label><input class="input" id="profile-time-zone" list="time-zone-options" value="${esc(p.onboarding_data?.timeZone||state.timeZone)}" maxlength="80"><datalist id="time-zone-options">${zones}</datalist><small class="muted">Used to decide when your nutrition day resets at midnight.</small></div><button class="button primary" data-action="save-profile">SAVE PROFILE</button></div>`)}${card('Account',`<p class="muted small">${esc(state.session.user.email||'Signed in')}</p><p class="small muted">Profile, workouts, saved routines and nutrition use the shared Supabase project.</p><button class="button" data-action="refresh">SYNC NOW</button><br><br><button class="button" data-action="signout">SIGN OUT</button>`)}</div>`}
function openModal(title,body,actions=''){modal.innerHTML=`<div class="modal-inner"><div class="modal-head"><h2>${title}</h2><button class="button" data-action="close-modal">CLOSE</button></div>${body}${actions?`<div class="actions">${actions}</div>`:''}</div>`;if(!modal.open)modal.showModal()}
function closeModal(){modal.close();modal.innerHTML=''}
function field(label,name,type='text',value='',attrs=''){return `<div class="field"><label>${label}</label><input class="input" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function showFoodForm(){openModal('Create a saved food',`<form id="food-form" class="form-grid">${field('Food name','name','text','','required maxlength="80"')}${field('Brand (optional)','brand')}<div class="field"><label>Serving amount</label><input class="input" name="servingAmount" type="number" min="0.01" step="any" value="1" required></div><div class="field"><label>Serving unit</label><select name="servingUnit">${['piece','egg','spoon','teaspoon','tablespoon','cup','serving','g','ml'].map(v=>`<option>${v}</option>`).join('')}</select></div><p class="muted small full">Enter macros for this whole serving, for example 1 roti or 2 eggs.</p>${field('Calories (kcal)','calories','number','0','min="0" step="any" required')}${field('Protein (g)','protein','number','0','min="0" step="any"')}${field('Carbohydrates (g)','carbs','number','0','min="0" step="any"')}${field('Fat (g)','fat','number','0','min="0" step="any"')}</form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="save-food">SAVE FOOD</button>`)}
function showQuantityForm(food){openModal(`Log ${esc(food.name)}`,`<form id="quantity-form" data-id="${esc(food.id)}"><p class="muted small">One serving is ${f(food.servingAmount,2)} ${esc(food.servingUnit)}. Change quantity to see the total.</p>${field(`Quantity (${esc(food.servingUnit)})`,'quantity','number','1','min="0.01" max="100" step="any" required')}<div id="quantity-preview" class="notice" style="margin-top:12px"></div></form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="confirm-food-log">LOG FOOD</button>`);const input=modal.querySelector('[name="quantity"]');const update=()=>{const q=n(input.value),t={cal:food.calories*q,p:food.proteinGrams*q,c:food.carbsGrams*q,fat:food.fatGrams*q};modal.querySelector('#quantity-preview').textContent=`Total · ${f(t.cal)} kcal · P ${f(t.p,1)} g · C ${f(t.c,1)} g · F ${f(t.fat,1)} g`};input.addEventListener('input',update);update()}
function exerciseOptionsHtml(query='',preserveSelection=true){const form=modal.querySelector('#routine-form'),selected=new Set(preserveSelection&&form?[...new FormData(form).getAll('exercises')]:[]),needle=query.trim().toLowerCase();const matches=exerciseChoices.map((exercise,index)=>({exercise,index})).filter(({exercise})=>!needle||exercise.some(x=>x.toLowerCase().includes(needle)));const visible=needle?matches.slice(0,80):matches.slice(0,25);return visible.map(({exercise,index})=>`<label class="list-row exercise-choice"><span><input type="checkbox" name="exercises" value="${index}" ${selected.has(String(index))?'checked':''}> ${exerciseGlyph({exercise:{name:exercise[0],muscleGroup:exercise[1],equipment:exercise[2]}})} ${esc(exercise[0])}</span><small>${esc(exercise[1])} · ${esc(exercise[2])}</small></label>`).join('')||'<p class="muted small">No exercises match that search.</p>'}
function showRoutineForm(coachedAthlete=null){state.coachedAthlete=coachedAthlete;openModal(coachedAthlete?`Create workout for ${esc(coachedAthlete.name)}`:'Build a workout',`<form id="routine-form">${coachedAthlete?`<input type="hidden" name="coachAthleteId" value="${esc(coachedAthlete.id)}"><input type="hidden" name="coachAthleteName" value="${esc(coachedAthlete.name)}">`:''}<div class="field"><label>Workout name</label><input class="input" name="title" required maxlength="60" placeholder="Push, Pull, Full body…"></div><div class="field" style="margin-top:12px"><label>Exercises · select in workout order</label><input class="input" id="exercise-search" type="search" placeholder="Search the exercise library" autocomplete="off"><div id="exercise-results" class="exercise-results stack">${exerciseOptionsHtml('',false)}</div>${exerciseChoices.length<=starterExercises.length?'<button type="button" class="button" data-action="download-exercises">DOWNLOAD THE FULL EXERCISE LIBRARY</button>':'<small class="muted">Downloaded exercise metadata is saved on this device; illustrations are not downloaded. <a href="https://repdb.co" target="_blank" rel="noopener noreferrer nofollow">Exercise data by RepDB (repdb.co)</a>.</small>'}</div><div class="form-grid" style="margin-top:12px">${field('Working sets per exercise','sets','number','3','min="3" max="12" required')}${field('Target reps per set','reps','number','8','min="1" max="100" required')}</div></form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="save-routine">SAVE WORKOUT</button>`)}
async function saveRoutineFromForm(){const form=modal.querySelector('#routine-form'),fd=new FormData(form),chosen=fd.getAll('exercises').map(Number),title=String(fd.get('title')||'').trim(),sets=n(fd.get('sets'),3),reps=n(fd.get('reps'),8);if(!title||!chosen.length)throw new Error('Name the workout and choose at least one exercise.');const id=uid(),exercises=chosen.map(index=>{const [name,muscleGroup,equipment]=exerciseChoices[index];return{id:uid(),exercise:{id:uid(),name,muscleGroup,equipment},restTimerSeconds:60,notes:'',targetRepMin:reps,targetRepMax:reps+2,weightIncrementKg:2.5,sets:Array.from({length:sets},(_,i)=>({id:uid(),setNumber:i+1,setType:'WORKING',targetWeightKg:0,targetReps:reps}))}});const definition={id,userId:state.session.user.id,isCustom:true,title,notes:'',exercises,folder:'CUSTOM'};const coachAthleteId=fd.get('coachAthleteId');if(coachAthleteId){await rpc('save_coached_routine',{p_athlete_id:coachAthleteId,p_id:id,p_title:title,p_notes:'',p_definition:definition});state.coachedAthlete=null;closeModal();await refreshData();flash(`Workout created for ${fd.get('coachAthleteName')||'your athlete'}.`);return}const row={id,user_id:state.session.user.id,title,notes:'',definition};await db('routines?on_conflict=id',{method:'POST',body:row,prefer:'resolution=merge-duplicates,return=minimal'});state.coachedAthlete=null;closeModal();await refreshData();flash('Workout saved to your account.')}
function startWorkout(id){const row=state.routines.find(x=>x.id===id);if(!row)throw new Error('This workout is no longer available.');const d=row.definition||{};state.activeWorkout={routineId:row.id,title:row.title||d.title||'Workout',startAt:Date.now(),exercises:(d.exercises||[]).map(e=>({...e,sets:(e.sets||[]).map(s=>({...s,weightKg:n(s.targetWeightKg),reps:n(s.targetReps),completed:true}))}))};persistWorkout();state.page='workouts';showWorkoutLogger()}
function captureWorkoutFormInputs(){const w=state.activeWorkout,form=modal.querySelector('#workout-form');if(!w||!form)return;const values=new FormData(form);w.exercises.forEach((exercise,i)=>exercise.sets.forEach((set,j)=>{set.weightKg=values.get(`weight_${i}_${j}`)??set.weightKg;set.reps=values.get(`reps_${i}_${j}`)??set.reps}))}
function removeWorkoutExerciseFromList(exercises,index){if(!Array.isArray(exercises)||exercises.length<=1||!Number.isInteger(index)||index<0||index>=exercises.length)return false;exercises.splice(index,1);return true}
function replaceWorkoutExerciseInList(exercises,index,replacement){const old=Array.isArray(exercises)?exercises[index]:null;if(!old||!Array.isArray(replacement)||replacement.length<3)return null;const previousName=old.exercise.name,[name,muscleGroup,equipment]=replacement;old.exercise={...old.exercise,name,muscleGroup,equipment};return {previousName,name}}
function showWorkoutLogger(){if(!state.activeWorkout)return;const w=state.activeWorkout,profileWeight=profileBodyWeightKg();const content=`<form id="workout-form"><p class="muted small">Log each completed set. Bodyweight movements ask for reps only; their volume uses an exercise-specific share of your profile weight. Reorder, replace, or remove exercises as needed.</p>${w.exercises.map((ex,i)=>{const load=effectiveBodyweightLoadKg(ex),isBodyweight=load!==null;return `<section class="card"><div class="row between"><div class="row exercise-title">${exerciseGlyph(ex)}<h3>${esc(ex.exercise.name)}</h3></div><div class="row"><button class="button" type="button" data-action="replace-workout-exercise" data-index="${i}">REPLACE</button><button class="button danger" type="button" data-action="remove-workout-exercise" data-index="${i}" ${w.exercises.length<=1?'disabled title="A workout must keep at least one exercise."':''}>REMOVE</button><button class="button" type="button" data-action="move-workout-exercise" data-index="${i}" data-delta="-1" ${i===0?'disabled':''} aria-label="Move ${esc(ex.exercise.name)} up">↑</button><button class="button" type="button" data-action="move-workout-exercise" data-index="${i}" data-delta="1" ${i===w.exercises.length-1?'disabled':''} aria-label="Move ${esc(ex.exercise.name)} down">↓</button></div></div>${isBodyweight?(profileWeight>0?`<p class="muted small">BODYWEIGHT · ${Math.round(bodyweightLoadFraction(ex.exercise?.name,ex.exercise?.equipment)*100)}% of profile weight · ${f(load,1)} kg per rep from ${f(profileWeight,1)} kg</p>`:`<p class="muted small">BODYWEIGHT · reps only · add body weight in Profile to estimate volume</p>`):''}${ex.sets.map((s,j)=>`<div class="form-grid" style="margin-bottom:8px">${isBodyweight?'':`<div class="field"><label>Set ${j+1} · weight (kg)</label><input class="input" type="number" min="0" step="0.5" name="weight_${i}_${j}" value="${n(s.weightKg,n(s.targetWeightKg))}" required></div>`}<div class="field"><label>Set ${j+1} · reps</label><input class="input" type="number" min="0" max="1000" name="reps_${i}_${j}" value="${n(s.reps,n(s.targetReps))}" required></div></div>`).join('')}</section>`}).join('')}</form>`;openModal(esc(w.title),content,`<button class="button danger" data-action="discard-web-workout">DISCARD</button><button class="button primary" data-action="finish-workout">FINISH & SAVE</button>`)}
function moveWorkoutExercise(index,delta){const w=state.activeWorkout;if(!w)return;captureWorkoutFormInputs();const destination=index+delta;if(index<0||index>=w.exercises.length||destination<0||destination>=w.exercises.length)return;const [exercise]=w.exercises.splice(index,1);w.exercises.splice(destination,0,exercise);persistWorkout();showWorkoutLogger()}
function removeWorkoutExercise(index){const w=state.activeWorkout;if(!w)return;captureWorkoutFormInputs();if(!removeWorkoutExerciseFromList(w.exercises,index))return;persistWorkout();showWorkoutLogger();flash('Exercise removed from this workout.')}
function replacementMuscles(muscle){switch(String(muscle||'').toLowerCase()){case'legs':case'lower body':return new Set(['legs','quads','hamstrings','glutes','calves']);case'core':return new Set(['core','abs','obliques']);case'arms':return new Set(['arms','biceps','triceps','forearms']);default:return new Set([String(muscle||'').toLowerCase()])}}
function showReplaceWorkoutExercise(index,query=''){const w=state.activeWorkout,old=w?.exercises[index];if(!old)return;captureWorkoutFormInputs();state.replaceExerciseIndex=index;const compatible=replacementMuscles(old.exercise.muscleGroup);const needle=query.trim().toLowerCase();const candidates=exerciseChoices.map((x,i)=>({x,i})).filter(({x})=>compatible.has(String(x[1]).toLowerCase())&&!x[0].toLowerCase().includes(old.exercise.name.toLowerCase())&&(!needle||x.some(v=>v.toLowerCase().includes(needle)))).sort((a,b)=>Number(b.x[2].toLowerCase()===String(old.exercise.equipment||'').toLowerCase())-Number(a.x[2].toLowerCase()===String(old.exercise.equipment||'').toLowerCase()));const results=candidates.slice(0,80).map(({x,i})=>`<button type="button" class="list-row" data-action="confirm-workout-replacement" data-choice="${i}"><span>${exerciseGlyph({exercise:{name:x[0],muscleGroup:x[1],equipment:x[2]}})} <strong>${esc(x[0])}</strong></span><small>${esc(x[1])} · ${esc(x[2])}</small></button>`).join('')||'<p class="muted small">No compatible exercises match. Download the full library or try another search.</p>';openModal(`Replace ${esc(old.exercise.name)}`,`<p class="muted small">Choose a similar muscle-group movement. Your set count, weights, reps and notes will carry over.</p><input class="input" id="replace-exercise-search" type="search" placeholder="Search compatible exercises" value="${esc(query)}" autocomplete="off"><div id="replace-exercise-results" class="list" style="margin-top:10px">${results}</div>${exerciseChoices.length<=starterExercises.length?'<button class="button" type="button" data-action="download-exercises">DOWNLOAD THE FULL EXERCISE LIBRARY</button>':''}`,`<button class="button" data-action="cancel-replace-workout-exercise">CANCEL</button>`)}
function replaceWorkoutExercise(choice){const w=state.activeWorkout,index=state.replaceExerciseIndex;if(!w)return;const result=replaceWorkoutExerciseInList(w.exercises,index,exerciseChoices[choice]);if(!result)return;persistWorkout();showWorkoutLogger();flash(`${result.previousName} replaced with ${result.name}.`)}
function handleActiveWorkoutAction(action,el){if(action==='remove-workout-exercise'){removeWorkoutExercise(Number(el.dataset.index));return true}if(action==='replace-workout-exercise'){showReplaceWorkoutExercise(Number(el.dataset.index));return true}if(action==='confirm-workout-replacement'){replaceWorkoutExercise(Number(el.dataset.choice));state.replaceExerciseIndex=null;return true}if(action==='cancel-replace-workout-exercise'){state.replaceExerciseIndex=null;showWorkoutLogger();return true}if(action==='download-exercises'&&Number.isInteger(state.replaceExerciseIndex)){const index=state.replaceExerciseIndex,query=modal.querySelector('#replace-exercise-search')?.value||'';downloadExerciseLibrary().then(()=>showReplaceWorkoutExercise(index,query)).catch(handleError);return true}return false}
async function finishWorkout(){const form=modal.querySelector('#workout-form');if(!form.reportValidity())return;const fd=new FormData(form),w=state.activeWorkout;const exerciseLogs=w.exercises.map((ex,i)=>({...{id:ex.id||uid(),exercise:ex.exercise,notes:ex.notes||''},sets:ex.sets.map((s,j)=>({id:s.id||uid(),setNumber:j+1,setType:s.setType||'WORKING',weightKg:effectiveBodyweightLoadKg(ex)??n(fd.get(`weight_${i}_${j}`)),reps:n(fd.get(`reps_${i}_${j}`)),rpe:null,targetRepMin:n(ex.targetRepMin,8),targetRepMax:n(ex.targetRepMax,10),completed:true}))}));const all=exerciseLogs.flatMap(e=>e.sets).filter(s=>s.completed),volume=exerciseLogs.reduce((a,e)=>a+e.sets.reduce((b,s)=>b+s.weightKg*s.reps,0),0),now=Date.now();const session={id:uid(),user_id:state.session.user.id,routine_id:w.routineId||null,title:w.title,started_at:new Date(w.startAt).toISOString(),ended_at:new Date(now).toISOString(),duration_seconds:Math.max(0,Math.round((now-w.startAt)/1000)),total_volume_kg:volume,total_reps:all.reduce((a,s)=>a+s.reps,0),rpe:null,exercise_logs:exerciseLogs};await db('workout_sessions?on_conflict=id',{method:'POST',body:session,prefer:'resolution=merge-duplicates,return=minimal'});state.activeWorkout=null;persistWorkout();closeModal();state.page='workouts';await refreshData();flash('Workout saved. Your journey is updated.')}
function formValue(id){return document.querySelector(`#${id}`)?.value?.trim()||''}
async function changeDate(date){if(!date||date>state.today)return;state.date=date;try{const rows=await db('daily_nutrition',{query:`select=*&user_id=eq.${encodeURIComponent(state.session.user.id)}&date=eq.${date}&limit=1`});state.nutrition=normalizeNutrition(rows?.[0]);render()}catch(e){handleError(e)}}
function physicalFoodGrams(amount,unit){return unit==='g'&&Number.isFinite(Number(amount))&&Number(amount)>0?Number(amount):0}
async function persistSavedFood(food){const unit=food.servingUnit||'g',usesMass=unit==='g'||unit==='ml',legacy=usesMass?food.servingGrams:100,factor=100/legacy;const row={id:food.id,user_id:state.session.user.id,source:'manual',name:food.name,brand:food.brand||'',serving_grams:legacy,serving_amount:food.servingAmount,serving_unit:unit,calories_per_100g:food.calories*factor,protein_per_100g:food.proteinGrams*factor,carbs_per_100g:food.carbsGrams*factor,fat_per_100g:food.fatGrams*factor,calories_per_serving:food.calories,protein_per_serving:food.proteinGrams,carbs_per_serving:food.carbsGrams,fat_per_serving:food.fatGrams};await db('user_foods?on_conflict=id',{method:'POST',body:row,prefer:'resolution=merge-duplicates,return=minimal'})}
async function dispatchAction(action,el){const id=el?.dataset.id;switch(action){case'close-modal':closeModal();break;case'signout':signOut();break;case'refresh':await refreshData();flash('Account synced.');break;case'toggle-workout-history':state.workoutHistoryExpanded=!state.workoutHistoryExpanded;render();break;case'toggle-home-workout-history':state.homeWorkoutHistoryExpanded=!state.homeWorkoutHistoryExpanded;render();break;case'toggle-auth':state.authMode=state.authMode==='signup'?'signin':'signup';state.message='';render();break;case'reset-password':{const email=prompt('Email address for password reset:');if(email)try{await authRequest(`recover?redirect_to=${encodeURIComponent(appCallbackUrl())}`,{email});flash('If that email has an account, a reset link will be sent.')}catch(e){handleError(e)}break}case'new-food':showFoodForm();break;case'save-food':{const form=modal.querySelector('#food-form');if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form));const food={id:uid(),name:String(d.name).trim(),brand:String(d.brand||'').trim(),servingAmount:n(d.servingAmount),servingUnit:d.servingUnit,servingGrams:n(d.servingAmount),calories:Math.round(n(d.calories)),proteinGrams:n(d.protein),carbsGrams:n(d.carbs),fatGrams:n(d.fat)};await persistSavedFood(food);closeModal();await refreshData();flash(`${food.name} saved to My Foods.`);break}case'log-saved-food':{const food=state.foods.find(x=>x.id===id);if(food)showQuantityForm(food);break}case'confirm-food-log':{const form=modal.querySelector('#quantity-form');if(!form.reportValidity())return;const food=state.foods.find(x=>x.id===form.dataset.id);if(!food)throw new Error('Saved food not found.');const q=n(new FormData(form).get('quantity')),serving=n(food.servingAmount,1);const entry={id:uid(),name:food.name,calories:Math.round(food.calories*q),proteinGrams:food.proteinGrams*q,carbsGrams:food.carbsGrams*q,fatGrams:food.fatGrams*q,grams:physicalFoodGrams(serving,food.servingUnit)*q,servingAmount:serving*q,servingUnit:food.servingUnit,brand:food.brand||'',loggedAtEpochMs:Date.now()};if(entry.calories>20000||entry.proteinGrams>3000||entry.carbsGrams>3000||entry.fatGrams>3000||entry.servingAmount>5000){flash('That quantity exceeds the supported maximum for one food log.','error');return}await persistNutrition({...state.nutrition,foods:[...(state.nutrition.foods||[]),entry]});closeModal();flash(`${f(q,2)} ${food.servingUnit} of ${food.name} logged.`);break}case'remove-food':{await persistNutrition({...state.nutrition,foods:state.nutrition.foods.filter(x=>x.id!==id)});flash('Food removed from this day.');break}case'delete-saved-food':{if(!confirm('Delete this saved food from My Foods? Existing food logs will stay.'))return;await db('user_foods',{method:'DELETE',query:`id=eq.${encodeURIComponent(id)}&user_id=eq.${encodeURIComponent(state.session.user.id)}`});await refreshData();flash('Saved food deleted.');break}case'add-water':{const amount=n(el.dataset.value),next=n(state.nutrition.water_ml)+amount;if(next>20000)throw new Error('Daily water total is already at the app limit.');await persistNutrition({...state.nutrition,water_ml:next});flash(`${amount} ml water logged.`);break}case'water-custom':{const amount=Number(prompt('Water amount in millilitres (1–5,000):'));if(Number.isInteger(amount)&&amount>0&&amount<=5000){const next=n(state.nutrition.water_ml)+amount;if(next<=20000){await persistNutrition({...state.nutrition,water_ml:next});flash(`${amount} ml water logged.`)}}break}case'date-prev':{const d=new Date(`${state.date}T12:00:00`);d.setDate(d.getDate()-1);await changeDate(d.toISOString().slice(0,10));break}case'date-next':{const d=new Date(`${state.date}T12:00:00`);d.setDate(d.getDate()+1);await changeDate(d.toISOString().slice(0,10));break}case'new-routine':showRoutineForm();break;case'request-coach':{const form=document.querySelector('#coach-request-form');if(!form.reportValidity())return;const username=String(new FormData(form).get('username')||'').trim().replace(/^@/,'').toLowerCase();await rpc('request_coach',{p_username:username});await refreshData();flash('Coach request sent. They need to accept before creating workouts.');break}case'respond-coach-request':await rpc('respond_coach_request',{p_relationship_id:id,p_accept:el.dataset.accept==='true'});await refreshData();flash(el.dataset.accept==='true'?'Coach connection accepted.':'Coach request declined.');break;case'end-coach-relationship':if(!confirm('End this coach connection?'))return;await rpc('end_coach_relationship',{p_relationship_id:id});await refreshData();flash('Coach connection ended.');break;case'create-coached-workout':showRoutineForm({id,name:el.dataset.name||'athlete'});break;case'download-exercises':await downloadExerciseLibrary();if(modal.open)showRoutineForm(state.coachedAthlete);break;case'save-routine':await saveRoutineFromForm();break;case'start-workout':startWorkout(id);break;case'resume-workout':showWorkoutLogger();break;case'move-workout-exercise':moveWorkoutExercise(Number(el?.dataset.index),Number(el?.dataset.delta));break;case'finish-workout':await finishWorkout();break;case'delete-session':{if(!confirm('Delete this completed workout? This removes it from your history and XP.'))return;await db('workout_sessions',{method:'DELETE',query:`id=eq.${encodeURIComponent(id)}&user_id=eq.${encodeURIComponent(state.session.user.id)}`});state.sessions=state.sessions.filter(s=>s.id!==id);render();flash('Completed workout deleted.');break}case'discard-web-workout':if(confirm('Discard this workout?')){state.activeWorkout=null;persistWorkout();closeModal();render()}break;case'view-routine':{const r=state.routines.find(x=>x.id===id);if(r){const ex=r.definition.exercises||[];openModal(esc(r.title),`<div class="list">${ex.map(x=>`<div class="list-row"><div class="row exercise-title">${exerciseGlyph(x)}<span><strong>${esc(x.exercise?.name)}</strong><small>${esc(x.exercise?.muscleGroup)} · ${(x.sets||[]).length} sets · ${n(x.targetRepMin,8)}–${n(x.targetRepMax,10)} reps</small></span></div></div>`).join('')}</div>`,`<button class="button primary" data-action="start-workout" data-id="${esc(id)}">START WORKOUT</button>`) }break}case'create-clan':openModal('Build a Clan',`<form id="clan-form" class="stack">${field('Clan name','name','text','','required maxlength="40"')}${field('Gym (optional)','gym','text','','maxlength="60"')}</form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="save-clan">CREATE CLAN</button>`);break;case'save-clan':{const d=Object.fromEntries(new FormData(modal.querySelector('#clan-form')));await rpc('create_clan',{p_name:String(d.name).trim(),p_gym_name:String(d.gym||'').trim()});closeModal();await refreshData();flash('Clan created. Share the invite code with your members.');break}case'join-clan':openModal('Join a Clan',`<form id="join-form">${field('Invite code','code','text','','required maxlength="32"')}</form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="join-clan-confirm">JOIN</button>`);break;case'join-clan-confirm':{const code=new FormData(modal.querySelector('#join-form')).get('code');await rpc('join_clan',{p_invite_code:String(code).trim().toUpperCase()});closeModal();await refreshData();flash('You joined the Clan.');break}case'open-clan':{const c=state.clans.find(x=>x.id===id);if(c)showClan(c);break}case'create-challenge':{const clanId=id||state.activeClan?.id;openModal('Challenge a lift',`<form id="challenge-form" class="stack">${field('Lift name','lift','text','','required maxlength="50"')}${field('Target weight','weight','number','','required min="0.5" step="0.5"')}<div class="field"><label>Weight unit</label><select name="unit"><option>kg</option><option>lb</option></select></div><div class="field"><label>Challenge ends</label><input class="input" name="expires" type="date" value="${new Date(Date.now()+7*86400000).toISOString().slice(0,10)}" required></div><input type="hidden" name="clanId" value="${esc(clanId)}"></form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="save-challenge">CREATE CHALLENGE</button>`);break}case'save-challenge':{const d=Object.fromEntries(new FormData(modal.querySelector('#challenge-form')));await rpc('create_clan_challenge',{p_clan_id:d.clanId,p_lift_name:d.lift,p_target_weight:n(d.weight),p_weight_unit:d.unit,p_expires_at:new Date(`${d.expires}T23:59:59`).toISOString()});closeModal();await refreshData();flash('Lift challenge created.');break}case'log-challenge':{const value=Number(prompt('Your best lift result (kg/lb as challenge specifies):'));if(Number.isFinite(value)&&value>=0)await rpc('log_challenge_result',{p_challenge_id:id,p_best_weight:value});flash('Challenge result logged.');break}case'physio':openModal('Physiotherapy · Coming soon',physioConsultationContent());break;case'save-profile':await saveProfile();break;case'set-username':await chooseUsername();break;case'toggle-public':await setPublic(el.checked);break;default:break}}
root.addEventListener('click',event=>{const nav=event.target.closest('[data-nav]');if(nav){state.page=nav.dataset.nav;render();if(state.page==='community')loadUserName().catch(()=>{});return}const action=event.target.closest('[data-action]');if(action)dispatchAction(action.dataset.action,action).catch(handleError)});
root.addEventListener('change',event=>{if(event.target.matches('[data-action="muscle-period"]')){state.musclePeriod=event.target.value==='all'?'all':Number(event.target.value);render()}});
root.addEventListener('change',event=>{if(event.target.id==='nutrition-date')changeDate(event.target.value).catch(handleError);if(event.target.matches('[data-action="toggle-public"]'))dispatchAction('toggle-public',event.target).catch(handleError)});
modal.addEventListener('click',event=>{const action=event.target.closest('[data-action]');if(action)dispatchAction(action.dataset.action,action).catch(handleError)});
modal.addEventListener('input',event=>{if(event.target.id==='exercise-search'){const target=modal.querySelector('#exercise-results');if(target)target.innerHTML=exerciseOptionsHtml(event.target.value)}});
root.addEventListener('submit',event=>{if(event.target.id==='auth-form'){event.preventDefault();const d=Object.fromEntries(new FormData(event.target));signIn(String(d.email).trim(),String(d.password),state.authMode==='signup');}});
async function saveProfile(){const id=state.session.user.id,old=state.profile||{},requestedZone=String(document.querySelector('#profile-time-zone').value||'').trim(),weightText=String(document.querySelector('#profile-weight').value||'').trim(),weightUnit=document.querySelector('#profile-weight-unit').value;try{new Intl.DateTimeFormat('en',{timeZone:requestedZone})}catch{throw new Error('Enter a valid time zone such as Asia/Kolkata or America/New_York.')}let weightValue=null;if(weightText){weightValue=Number(weightText);const weightKg=weightUnit==='lb'?weightValue/2.2046226218:weightValue;if(!Number.isFinite(weightKg)||weightKg<30||weightKg>350)throw new Error('Enter a body weight that converts to 30–350 kg.')}const onboarding={...(old.onboarding_data||{}),sessionsPerWeek:n(document.querySelector('#profile-goal').value,3),timeZone:requestedZone};const row={id,display_name:formValue('profile-name')||'THE BUILDER',name:formValue('profile-name')||'THE BUILDER',gender:document.querySelector('#profile-gender').value,training_path:document.querySelector('#profile-path').value,path:document.querySelector('#profile-path').value,height_unit:old.height_unit||'cm',weight_value:weightValue,weight_unit:weightUnit,marketing_opt_in:old.marketing_opt_in||false,is_public:old.is_public||false,onboarding_data:onboarding};await db('profiles?on_conflict=id',{method:'POST',body:row,prefer:'resolution=merge-duplicates,return=minimal'});state.timeZone=requestedZone;localStorage.setItem('gbNutritionTimeZone',requestedZone);await refreshData();flash('Profile saved.')}
function chooseUsername(){if(state.username){flash(`Your community username is @${esc(state.username)}.`);return}openModal('Choose a username',`<form id="username-form">${field('Username','username','text','','required minlength="3" maxlength="20" pattern="[a-z][a-z0-9_]{2,19}" autocomplete="username"')}<p class="muted small">Start with a letter. Use 3–20 lowercase letters, numbers or underscores.</p></form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="save-username">CLAIM USERNAME</button>`)}
async function saveUsername(){const form=modal.querySelector('#username-form');if(!form.reportValidity())return;const value=String(new FormData(form).get('username')||'').trim().toLowerCase();if(!/^[a-z][a-z0-9_]{2,19}$/.test(value))throw new Error('Start with a letter and use 3–20 lowercase letters, numbers or underscores.');await rpc('claim_username',{p_username:value});state.username=value;if(state.profile)state.profile={...state.profile,username:value};closeModal();flash(`Your username is @${value}.`)}
async function loadUserName(){if(state.username||state.usernameLoading)return;state.usernameLoading=true;try{const rows=await db('usernames',{query:`select=username&user_id=eq.${encodeURIComponent(state.session.user.id)}&limit=1`});state.username=rows?.[0]?.username||'';if(state.profile)state.profile={...state.profile,username:state.username};render()}finally{state.usernameLoading=false}}
async function setPublic(value){const isPublic=Boolean(value);await db('profiles',{method:'PATCH',query:`id=eq.${encodeURIComponent(state.session.user.id)}`,body:{is_public:isPublic},prefer:'return=minimal'});state.profile={...(state.profile||{}),is_public:isPublic};flash(isPublic?'Profile is public.':'Profile is private.');render()}
document.addEventListener('submit',event=>{if(event.target.id==='food-form'){event.preventDefault();}if(event.target.id==='routine-form')event.preventDefault();if(event.target.id==='workout-form')event.preventDefault();if(event.target.id==='quantity-form')event.preventDefault()});
// Community data is loaded through the same authenticated, RLS-protected RPCs as Android.
state.challengeEntries = state.challengeEntries || {};
state.publicProfiles = state.publicProfiles || [];
state.publicRoutines = state.publicRoutines || [];
state.activeClan = state.activeClan || null;
async function loadChallenges(clanId){const target=clanId||state.activeClan?.id;if(!target)return;state.activeClan=state.clans.find(c=>c.id===target)||state.activeClan;state.challenges=await db('clan_challenges',{query:`select=*&clan_id=eq.${encodeURIComponent(target)}&order=expires_at.asc`});state.challengeEntries={};for(let i=0;i<state.challenges.length;i+=8){await Promise.all(state.challenges.slice(i,i+8).map(async c=>{state.challengeEntries[c.id]=await rpc('challenge_entries',{p_id:c.id}).catch(()=>[])}))}render()}
async function showClan(clan){state.activeClan=clan;await loadChallenges(clan.id)}
function renderCommunity(){
  const clans=state.clans.map(c=>`<div class="list-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.gym_name||'Independent Clan')} · ${n(c.member_count)} members</small><small>Invite code <b class="gold">${esc(c.invite_code)}</b></small></div><button class="button" data-action="open-clan" data-id="${esc(c.id)}">OPEN</button></div>`).join('')||`<div class="empty">No Clans yet. Build one or join with an invite code.</div>`;
  const unread=state.notices.filter(x=>!x.read_at).map(x=>`<div class="list-row"><div><strong>${esc(x.message)}</strong><small>${new Date(x.created_at).toLocaleString()}</small></div><button class="button" data-action="mark-notice-read" data-id="${esc(x.id)}">MARK READ</button></div>`).join('');
  const challenges=state.activeClan?(state.challenges||[]).map(ch=>{const entries=state.challengeEntries?.[ch.id]||[];const board=entries.map((e,i)=>`<div class="list-row"><span><b class="gold">${i+1}.</b> ${esc(e.display_name)}</span><strong>${f(e.best_weight,1)} ${esc(ch.weight_unit)}</strong></div>`).join('')||`<p class="muted small">No results yet. Be the first to log a lift.</p>`;return `<section class="card"><div class="row between"><div><h3>${esc(ch.lift_name)}</h3><p class="muted small">Target ${f(ch.target_weight,1)} ${esc(ch.weight_unit)} · ends ${new Date(ch.expires_at).toLocaleDateString()}</p></div><button class="button primary" data-action="log-challenge" data-id="${esc(ch.id)}" ${new Date(ch.expires_at)<=new Date()?'disabled':''}>LOG RESULT</button></div><h3>LEADERBOARD</h3><div class="list">${board}</div></section>`}).join('')||`<div class="empty">No lift challenges yet. Start one for your Clan.</div>`:'';
  const profiles=(state.publicProfiles||[]).map(p=>`<div class="list-row"><div><strong>${esc(p.display_name)}</strong><small>@${esc(p.username||'')} · ${esc(p.training_path||'BUILDER')}</small></div><button class="button" data-action="view-public-profile" data-id="${esc(p.user_id)}">VIEW WORKOUTS</button></div>`).join('')||`<div class="empty">Search for public profiles by username or display name.</div>`;
  const publicRoutines=(state.publicRoutines||[]).map(r=>`<div class="list-row"><div><strong>${esc(r.title)}</strong><small>${(r.definition?.exercises||[]).length} exercises</small></div><button class="button primary" data-action="copy-public-routine" data-id="${esc(r.id)}">COPY WORKOUT</button></div>`).join('');
  const coaching=(state.coachRelationships||[]).map(r=>{const athlete=r.athlete_id===state.session.user.id,person=athlete?r.coach_name:r.athlete_name,username=athlete?r.coach_username:r.athlete_username;if(r.status==='pending'&&!athlete)return `<div class="list-row"><span><strong>${esc(person)}</strong><small>@${esc(username||'')} wants you as coach</small></span><span class="row"><button class="button primary" data-action="respond-coach-request" data-id="${esc(r.id)}" data-accept="true">ACCEPT</button><button class="button" data-action="respond-coach-request" data-id="${esc(r.id)}" data-accept="false">DECLINE</button></span></div>`;const actions=r.status==='active'&&!athlete?`<button class="button primary" data-action="create-coached-workout" data-id="${esc(r.athlete_id)}" data-name="${esc(person)}">CREATE WORKOUT</button>`:'';return `<div class="list-row"><span><strong>${esc(person)}</strong><small>@${esc(username||'')} · ${r.status==='pending'?'Request pending':r.status==='active'?(athlete?'Your coach':'Athlete'):r.status}</small></span><span class="row">${actions}${r.status==='pending'||r.status==='active'?`<button class="button danger" data-action="end-coach-relationship" data-id="${esc(r.id)}">${r.status==='pending'?'CANCEL':'END'}</button>`:''}</span></div>`}).join('')||'<div class="empty">No coach connections yet.</div>';
  return `${head('THE GATHERING','Community','Build a Clan, challenge lifts, and share routines.',`<button class="button primary" data-action="create-clan">+ BUILD A CLAN</button>`)}${unread?card('Inbox',`<div class="list">${unread}</div>`):''}${card('Coach & athlete',`<p class="muted small">Request a coach by username. A coach can create workouts for you only after you accept; your history and health data stay private.</p><form id="coach-request-form" class="row"><input class="input" name="username" placeholder="Coach username" minlength="3" maxlength="20" required><button type="button" class="button primary" data-action="request-coach">REQUEST</button></form><div class="list" style="margin-top:10px">${coaching}</div>`)}<div class="grid two">${card('Your Clans',`<div class="list">${clans}</div><div class="row" style="margin-top:12px"><button class="button" data-action="join-clan">JOIN WITH CODE</button></div>`)}${card('Username & profile visibility',`<p class="muted small">Set a username so friends can find you. Enabling public discovery makes your saved workouts visible for friends to copy.</p><div class="row"><span class="gold">${state.username?`@${esc(state.username)}`:'No username set'}</span><button class="button" data-action="set-username" ${state.username?'disabled':''}>${state.username?'USERNAME SET':'CHOOSE USERNAME'}</button></div><label class="row" style="margin-top:14px"><input type="checkbox" data-action="toggle-public" ${state.profile?.is_public?'checked':''}> <span class="small">Allow my profile and saved workouts to be found</span></label>`)}${card('Find public workouts',`<form id="public-search-form" class="row"><input class="input" name="query" placeholder="Username or display name" maxlength="40"><button class="button" data-action="search-public">SEARCH</button></form><div class="list" style="margin-top:8px">${profiles}</div>${state.viewedProfile?`<h3 style="margin-top:16px">${esc(state.viewedProfile.display_name||'')}’S WORKOUTS</h3><div class="list">${publicRoutines||'<div class="empty">No saved workouts to share yet.</div>'}</div>`:''}`)}</div>${state.activeClan?`<section style="margin-top:20px"><div class="page-head"><div><div class="kicker">CLAN CHALLENGES</div><h2>${esc(state.activeClan.name)}</h2><p>Invite code <b class="gold">${esc(state.activeClan.invite_code)}</b></p></div><button class="button primary" data-action="create-challenge" data-id="${esc(state.activeClan.id)}">+ CHALLENGE A LIFT</button></div><div class="grid two">${challenges}</div></section>`:''}`
}
async function searchPublicProfiles(){const form=document.querySelector('#public-search-form');const query=String(new FormData(form).get('query')||'').trim().slice(0,40);if(query.length<2)throw new Error('Enter at least two characters to search.');state.publicProfiles=await rpc('search_public_profiles',{p_query:query});state.publicRoutines=[];state.viewedProfile=null;render()}
async function viewPublicProfile(userId){const profile=state.publicProfiles.find(p=>p.user_id===userId);if(!profile)return;state.viewedProfile=profile;state.publicRoutines=await db('routines',{query:`select=id,user_id,title,notes,definition&user_id=eq.${encodeURIComponent(userId)}&order=updated_at.desc`});render()}
async function copyPublicRoutine(id){const row=state.publicRoutines.find(r=>r.id===id);if(!row)throw new Error('That workout is no longer available.');const def=structuredClone(row.definition||{});def.id=uid();def.userId=state.session.user.id;def.isCustom=true;def.title=`Copy · ${String(row.title||def.title||'Workout').slice(0,60)}`;def.exercises=(def.exercises||[]).map(e=>({...e,id:uid(),exercise:{...e.exercise,id:uid()},sets:(e.sets||[]).map(s=>({...s,id:uid()}))}));await db('routines?on_conflict=id',{method:'POST',body:{id:def.id,user_id:state.session.user.id,title:def.title,notes:def.notes||'',definition:def},prefer:'resolution=merge-duplicates,return=minimal'});await refreshData();state.page='workouts';flash('Workout copied to your saved workouts.')}
async function markNoticeRead(id){await db('clan_notifications',{method:'PATCH',query:`id=eq.${encodeURIComponent(id)}&user_id=eq.${encodeURIComponent(state.session.user.id)}`,body:{read_at:new Date().toISOString()},prefer:'return=minimal'});state.notices=state.notices.map(x=>x.id===id?{...x,read_at:new Date().toISOString()}:x);render()}
function submitChallengeResult(id){const challenge=state.challenges.find(x=>x.id===id);if(!challenge)throw new Error('Challenge not found.');openModal('Log lift result',`<form id="challenge-result-form">${field(`Best ${esc(challenge.lift_name)} (${esc(challenge.weight_unit)})`,'weight','number','','required min="0.5" step="0.5"')}</form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="save-challenge-result" data-id="${esc(id)}">SUBMIT RESULT</button>`)}
async function saveChallengeResult(id){const form=modal.querySelector('#challenge-result-form');if(!form.reportValidity())return;const weight=n(new FormData(form).get('weight'));await rpc('log_challenge_result',{p_challenge_id:id,p_best_weight:weight});closeModal();await loadChallenges(state.activeClan.id);flash('Result submitted. The leaderboard is updated.')}
root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(!['open-clan','search-public','view-public-profile','copy-public-routine','mark-notice-read','log-challenge','save-challenge-result'].includes(action))return;event.preventDefault();event.stopImmediatePropagation();const run=async()=>{if(action==='open-clan'){const c=state.clans.find(x=>x.id===el.dataset.id);if(c)await showClan(c)}else if(action==='search-public')await searchPublicProfiles();else if(action==='view-public-profile')await viewPublicProfile(el.dataset.id);else if(action==='copy-public-routine')await copyPublicRoutine(el.dataset.id);else if(action==='mark-notice-read')await markNoticeRead(el.dataset.id);else if(action==='log-challenge')submitChallengeResult(el.dataset.id);else if(action==='save-challenge-result')await saveChallengeResult(el.dataset.id)};run().catch(handleError)},true);
modal.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(!['save-username','save-challenge-result'].includes(action))return;event.preventDefault();event.stopImmediatePropagation();const run=action==='save-username'?saveUsername():saveChallengeResult(el.dataset.id);Promise.resolve(run).catch(handleError)},true);
document.addEventListener('submit',event=>{if(event.target.id==='public-search-form')event.preventDefault()});
modal.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;if(handleActiveWorkoutAction(el.dataset.action,el)){event.preventDefault();event.stopImmediatePropagation()}},true);
modal.addEventListener('input',event=>{if(event.target.id==='replace-exercise-search'){const target=modal.querySelector('#replace-exercise-results');if(target)target.innerHTML=replacementChoicesHtml(state.replaceExerciseIndex,event.target.value)}});

function normalizeAvatarDimensions(raw={}){const keys=['heightPct','buildPct','shouldersPct','chestPct','armsPct','waistPct','hipsPct','thighsPct','calvesPct'];return Object.fromEntries(keys.map(key=>[key,Math.max(80,Math.min(120,n(raw?.[key],100)))]))}
function avatarDimensionMask(y,start,end,fade){const smooth=value=>{const t=Math.max(0,Math.min(1,value));return t*t*(3-2*t)};return smooth((y-start)/fade)*smooth((end-y)/fade)}
function avatarWidthScaleAt(y,raw){const d=normalizeAvatarDimensions(raw),band=Math.max(0,Math.min(1,y)),regional=(d.shouldersPct-100)*avatarDimensionMask(band,.19,.38,.065)+(d.chestPct-100)*avatarDimensionMask(band,.28,.49,.065)+(d.armsPct-100)*avatarDimensionMask(band,.22,.59,.07)*.55+(d.waistPct-100)*avatarDimensionMask(band,.40,.59,.07)+(d.hipsPct-100)*avatarDimensionMask(band,.50,.69,.065)+(d.thighsPct-100)*avatarDimensionMask(band,.60,.83,.07)+(d.calvesPct-100)*avatarDimensionMask(band,.76,.97,.06);return Math.max(.70,Math.min(1.45,d.buildPct/100+regional/100))}
function renderAvatarMorphCanvases(){const dims=normalizeAvatarDimensions(state.avatarDimensionsDraft||state.profile?.onboarding_data?.avatarDimensions);for(const canvas of root.querySelectorAll('canvas[data-avatar-morph]')){const img=canvas._avatarImage;if(!img?.complete||!img.naturalWidth)continue;const ctx=canvas.getContext('2d');if(!ctx)continue;const w=img.naturalWidth,h=img.naturalHeight,vertical=dims.heightPct/100,fit=Math.min(canvas.width/w,canvas.height/(h*vertical)),baseW=w*fit,displayH=h*fit*vertical,top=(canvas.height-displayH)/2,bands=Math.min(h,384);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.imageSmoothingEnabled=true;for(let i=0;i<bands;i++){const sy=Math.floor(i*h/bands),end=Math.min(h,Math.floor((i+1)*h/bands)),sh=Math.max(1,end-sy),scale=avatarWidthScaleAt((sy+end)/2/h,dims),dw=baseW*scale,dh=displayH*sh/h;ctx.drawImage(img,0,sy,w,sh,(canvas.width-dw)/2,top+displayH*sy/h,dw,dh+1)}}}
function renderAvatar(){const p=state.profile||{},xp=xpForSessions(state.sessions,targetPerWeek()),level=Math.floor(xp/1000)+1,stage=level>=10?3:level>=5?2:1,path=['SUPERHERO','TITAN'].includes(String(p.training_path||'').toUpperCase())?String(p.training_path).toLowerCase():'god',gender=String(p.gender||'Male').toLowerCase().includes('fem')?'female':'male',base=`${config.supabaseUrl.replace(/\/$/,'')}/storage/v1/object/public/godbuilder-site/avatarpack`;state.avatarDimensionsDraft=normalizeAvatarDimensions(p.onboarding_data?.avatarDimensions);const choices=[['GOD','male','God · Male'],['GOD','female','God · Female'],['SUPERHERO','male','Superhero · Male'],['SUPERHERO','female','Superhero · Female'],['TITAN','male','Titan · Male'],['TITAN','female','Titan · Female']];const image=(kind,sex,levelStage,extra='',morph=false)=>{const src=`${base}/avatar_${kind}_${sex}_stage_${levelStage}.png`;return `<div class="avatar-art ${extra}"><img class="avatar-base" src="${src}" alt="${kind} ${sex} avatar, stage ${levelStage}" loading="lazy" onerror="this.parentElement.classList.add('unavailable')">${morph?`<canvas class="avatar-morph" data-avatar-morph data-src="${src}" width="512" height="768" aria-label="Adjustable ${kind} ${sex} avatar"></canvas>`:''}<span class="avatar-fallback" aria-hidden="true">${kind}<small>${sex.toUpperCase()}</small></span></div>`};const modelCards=choices.map(([kind,sex,label])=>`<article class="avatar-choice ${kind.toLowerCase()===path&&sex===gender?'selected':''}">${image(kind.toLowerCase(),sex,1)}<div><strong>${label}</strong><small>${kind.toLowerCase()===path&&sex===gender?'CURRENT MODEL':'Set in Profile'}</small></div></article>`).join('');const basic=[['heightPct','Height'],['buildPct','Build'],['shouldersPct','Shoulders'],['waistPct','Waist']],advanced=[['chestPct','Chest'],['armsPct','Arms'],['hipsPct','Hips'],['thighsPct','Thighs'],['calvesPct','Calves']],dims=state.avatarDimensionsDraft,slider=([key,label])=>`<label class="dimension-control"><span>${label}<b data-dimension-value="${key}">${dims[key]}%</b></span><input type="range" min="80" max="120" step="5" value="${dims[key]}" data-avatar-dimension="${key}" aria-label="${label} proportion"></label>`;const editor=level<5?`<div class="locked-editor"><b>LEVEL 5 · BASIC EDITOR</b><p>Height, build, shoulders and waist unlock at Level 5. Advanced dimensions unlock at Level 10.</p></div>`:`<div class="avatar-dimension-grid">${basic.map(slider).join('')}${level>=10?`<div class="dimension-advanced"><b>ADVANCED · LEVEL 10</b>${advanced.map(slider).join('')}</div>`:`<div class="dimension-locked"><b>ADVANCED · LEVEL 10</b><small>Chest, arms, hips, thighs and calves unlock at Level 10.</small></div>`}</div><div class="row dimension-actions"><button class="button" data-action="reset-avatar-dimensions">RESET</button><button class="button primary" data-action="save-avatar-dimensions">SAVE MODEL</button></div>`;return `${head('AVATAR','Your avatar','Your training path, level and recovery journey in one place.')}<div class="grid two"><section class="card avatar-current"><div class="kicker">${esc(String(p.training_path||'GOD').toUpperCase())} PATH · ${gender.toUpperCase()}</div>${image(path,gender,stage,'avatar-main-art',true)}<h2>LEVEL ${level} · STAGE ${stage}</h2><p class="muted small">${f(xp)} total XP · ${stage===1?`${Math.max(0,4000-xp)} XP to Stage 2`:stage===2?`${Math.max(0,9000-xp)} XP to Stage 3`:'Stage 3 reached'}</p><div class="progress"><i style="width:${stage===1?Math.min(100,xp/40):stage===2?Math.min(100,(xp-4000)/50):100}%"></i></div><p class="muted small">The avatar follows your gender and training path from Profile. Stage artwork downloads on demand and stays cached on this device.</p><button class="button" data-nav="profile">EDIT PATH & PRESENTATION</button></section>${card('Six avatar models',`<p class="muted small">Choose a path and presentation in Profile. The stage shown here follows your workout XP.</p><div class="avatar-grid">${modelCards}</div>`)}</div><section class="card avatar-dimensions-card"><div class="row between"><div><div class="kicker">AVATAR FORGE</div><h2>Dimensions editor</h2><p class="muted small">Shape the downloaded artwork. This changes appearance only, not workout or health data.</p></div><span class="pill">${level<5?'UNLOCKS AT 5':level<10?'BASIC · ADVANCED AT 10':'FULL EDITOR'}</span></div>${editor}</section>`}
function physioConsultationContent(){return `<section class="stack"><div><strong>Dhruv Bawa, MPT (Neurology)</strong><p class="muted small">Registered Physiotherapist · Haryana State Council of Physiotherapy · Registration No. HSCP/PT/2025/3685</p><p class="muted small">Master’s degree in Neurological Physiotherapy. Specialties include neurological and stroke rehabilitation; spinal cord injury; Parkinson’s and geriatric rehabilitation; cognitive rehabilitation; musculoskeletal, neck, back, shoulder and knee care; post-surgical rehabilitation; gait, balance and functional training.</p><p class="muted small">English · Hindi · Punjabi</p><p class="muted small">Service area: India and online worldwide, subject to local regulations.</p></div><hr><div><strong>Written exercise consultation</strong><p class="muted small">Discuss symptoms, receive personalized exercises and a home program, and get progression guidance.</p><span class="pill">PAID SERVICE · COMING SOON</span></div><div><strong>Live video consultation</strong><p class="muted small">One-to-one consultation with rehabilitation history, functional screening, exercise guidance and follow-up.</p><span class="pill">PAID SERVICE · COMING SOON</span></div><div class="notice">Consultations are not bookable yet. Pricing will be shown before launch.</div></section>`}
const dispatchActionBeforeAvatarEditor=dispatchAction;dispatchAction=async function(action,el){if(action==='reset-avatar-dimensions'){state.avatarDimensionsDraft=normalizeAvatarDimensions();for(const input of root.querySelectorAll('[data-avatar-dimension]')){input.value='100';const out=root.querySelector(`[data-dimension-value="${input.dataset.avatarDimension}"]`);if(out)out.textContent='100%'}renderAvatarMorphCanvases();return}if(action==='save-avatar-dimensions'){if(Math.floor(xpForSessions(state.sessions,targetPerWeek())/1000)+1<5)throw new Error('Reach Level 5 to unlock avatar dimensions.');const dims=normalizeAvatarDimensions(state.avatarDimensionsDraft),onboarding={...(state.profile?.onboarding_data||{}),avatarDimensions:dims};await db('profiles',{method:'PATCH',query:`id=eq.${encodeURIComponent(state.session.user.id)}`,body:{onboarding_data:onboarding},prefer:'return=minimal'});state.profile={...state.profile,onboarding_data:onboarding};state.avatarDimensionsDraft=dims;await refreshData();flash('Avatar dimensions saved to your profile.');return}return dispatchActionBeforeAvatarEditor(action,el)};
root.addEventListener('input',event=>{const input=event.target.closest('[data-avatar-dimension]');if(!input)return;const key=input.dataset.avatarDimension;state.avatarDimensionsDraft=normalizeAvatarDimensions({...state.avatarDimensionsDraft,[key]:Number(input.value)});const output=root.querySelector(`[data-dimension-value="${key}"]`);if(output)output.textContent=`${state.avatarDimensionsDraft[key]}%`;renderAvatarMorphCanvases()});
root.addEventListener('load',event=>{if(event.target.matches?.('img.avatar-base')){const canvas=event.target.parentElement.querySelector('canvas[data-avatar-morph]');if(!canvas)return;const img=new Image();img.crossOrigin='anonymous';img.onload=()=>{canvas._avatarImage=img;canvas.parentElement.querySelector('.avatar-base')?.classList.add('morphed');renderAvatarMorphCanvases()};img.onerror=()=>{};img.src=canvas.dataset.src}},true);
